// Canonical teaching content. All numerical practice data are authored classroom examples.
export const lessons=[];
const p=(...s)=>s.map(x=>`<p>${x}</p>`).join('');
const list=(...s)=>'<ul>'+s.map(x=>`<li>${x}</li>`).join('')+'</ul>';
const eq=s=>`<div class="equation">${s}</div>`;
const table=(head,rows)=>'<table><thead><tr>'+head.map(x=>`<th>${x}</th>`).join('')+'</tr></thead><tbody>'+rows.map(r=>'<tr>'+r.map(c=>`<td>${c}</td>`).join('')+'</tr>').join('')+'</tbody></table>';
const S=(title,...parts)=>{const more=typeof parts.at(-1)==='object'?parts.pop():{};const note=parts.pop();return {title,body:parts.join(''),note,...more};};
const Q=(title,...parts)=>{const more=typeof parts.at(-1)==='object'?parts.pop():{};const note=parts.pop(),answer=parts.pop();return S(title,parts.join(''),note,{answer,...more});};
const chart=(kind,data,labels)=>`<div class="chart" data-chart='${JSON.stringify({kind,data,labels})}'></div>`;
const sim=kind=>`<div class="simulation" data-sim="${kind}"></div>`;
function L(day,title,target,materials,pacing,slides,exit,exitKey,route){lessons.push({day,title,target,materials,pacing,slides,exit,exitKey,route});}
L(1,'The briefing','Separate evidence from inference and name the measurements needed to predict a future position.','Notebook, briefing on screen, chart paper or shared document.','5 min launch • 8 min briefing • 12 min evidence sort • 15 min questions • 7 min model • 3 min exit',[
Q('A prediction needs information',p('A message says, “An object is approaching Earth.”','Write two things you would need to know before predicting where it will be next month.'),p('We need its <strong>current position</strong>, its <strong>velocity including direction</strong>, and the <strong>elapsed time</strong>. We also need to know whether its velocity changes.'),'Give one quiet minute before sharing. Accept size as relevant to consequences, then distinguish it from the quantities needed for a position prediction. Keep the initial questions for the end-of-unit comparison.',{tag:'Opening question'}),
S('2026-XJ: the classroom briefing',p('In our fictional scenario, observers have detected an asteroid approaching Earth’s neighborhood. The initial estimates of its path, speed, size, and composition remain uncertain.','The story places a possible encounter near graduation. <strong>That date is part of the story, not a result we have calculated.</strong>','Your job this year is to build and test explanations as new data arrive.'),'Read this aloud once, then let students annotate. State explicitly that 2026-XJ is an invented teaching case, not a NASA alert. Avoid adding an impact probability or claiming that approach guarantees collision.',{tag:'Fictional scenario',dark:true}),
S('Evidence, inference, and a question',table(['Category','Example'],[['Evidence stated in the briefing','Observers have detected an approaching object.'],['Inference that needs testing','The object will hit Earth.'],['Question we can investigate','How does its position change each day?']]),'Ask students to underline the source phrase supporting the evidence. Explain that an inference can be reasonable without being established. An unanswered question is productive when we can name evidence that would help answer it.'),
Q('The first evidence check',p('Classify each statement as stated evidence, an inference, or an open question.'),list('The exact future position is uncertain.','The asteroid will destroy the school.','What direction is the velocity?'),p('1. Stated evidence. 2. Unsupported inference. 3. Open question.','“Approaching” alone cannot establish a collision, size of damage, or exact arrival date.'),'Use three simultaneous hand signals. If students classify the second statement as evidence, return to the actual briefing and ask where it says that.',{tag:'Check together'}),
S('Notice and wonder',list('Individually: record two observations grounded in the briefing.','In a group: combine three notices and at least five questions.','Beside each question, name one measurement or observation that could help.','Choose one question to share and explain why it matters.'),'Allow sketches and oral rehearsal. Assign a reader, recorder, and evidence checker, combining roles as needed. Online learners complete the same table alone and compare with the example that follows.',{tag:'12-minute investigation'}),
Q('A stronger question',p('Rewrite “Is it bad?” as a question that could guide an investigation. Name evidence that would help answer it.'),p('One possible revision: “Will the asteroid’s predicted path intersect Earth’s position at the same time?”','Useful evidence: repeated position measurements, velocity direction, and uncertainties in both.'),'Accept other measurable questions such as size or composition, with an appropriate method. Do not demand the sample wording. Ask how the answer would change a decision.'),
S('Questions for a year of physics',table(['We want to know…','Tools we will build'],[['Where and when?','Motion graphs, vectors, forces'],['Why does the path curve?','Gravity and orbits'],['What happens in a collision?','Momentum and energy'],['How do we observe or respond?','Waves, thermal physics, electricity']]),'Use this as a brief orientation. Save student questions under these categories and return to them throughout the year. Social and ethical questions also matter, even when a physics calculation alone cannot settle them.'),
S('A model makes a testable prediction',p('A <strong>model</strong> is a simplified description with stated assumptions.','If an object keeps the same velocity, equal time intervals produce equal displacements. We can compare that prediction with new observations.'),eq('New position = starting position + change in position'),'Use a walker as the concrete example. Point to the initial location, then count two equal steps each second. Explain that a model may work for a short interval and need revision for a longer one.'),
Q('A tiny prediction we can test',p('Practice data: a cart is at 2 m, 4 m, and 6 m at 0 s, 1 s, and 2 s.','Predict its position at 3 s. State an assumption and an observation that would challenge it.'),p('<strong>8 m</strong>, if the cart continues gaining 2 m of position each second.','A new reading of 7 m would challenge the constant-velocity prediction. Check measurement quality and consider a changed motion model.'),'Have students say “if” with their prediction. This is the first model claim of the course. Numbers here are practice data, not asteroid measurements.'),
S('What a useful explanation contains',p('<strong>Claim:</strong> The cart should reach 8 m at 3 s.','<strong>Evidence:</strong> Position increased by 2 m in each observed second.','<strong>Reasoning:</strong> If that pattern continues, another second adds another 2 m.','<strong>Limit:</strong> A new force or an inaccurate measurement could change the result.'),'Invite students to improve their first answer rather than copy this verbatim. In an online lesson, pause here and rewrite the prediction with its assumption.'),
Q('Independent application',p('A second cart is at 10 m, 8 m, and 6 m at 0 s, 1 s, and 2 s. Predict the position at 4 s. Explain why the answer is smaller than 6 m.'),p('The cart loses 2 m of position each second. At 3 s it reaches 4 m, and at 4 s it reaches <strong>2 m</strong>, assuming the same motion continues.'),'Look for students who automatically add. Have them draw a number line and mark successive positions. This previews signed change without requiring formal vector vocabulary.',{tag:'Try independently'})
], 'State one thing the briefing establishes, one thing it does not establish, and one measurement needed for a prediction.','Establishes detection/approach with uncertainty. Does not establish impact or exact future position. Relevant measurements include current position and velocity with direction.','If evidence and inference blur, revisit the evidence sort before introducing motion vocabulary.');
L(2,'Position, distance, and displacement','Describe a route using an origin, signed position, total distance, and displacement.','Tape measure, floor tape, notebook. Online: sketch the marked positions.','5 min retrieve • 10 min explain • 12 min model • 15 min practice • 5 min compare • 3 min exit',[
Q('A return trip',p('You walk 4 m from a door and then return to the door.','How much ground did you cover? How far is your final position from your starting position?'),p('<strong>Distance = 8 m.</strong> <strong>Displacement = 0 m.</strong> The two answers describe different features of the same trip.'),'Collect both answers before naming the quantities. Ask students to trace the path for distance and point from start to finish for displacement.'),
S('A coordinate system makes position precise',list('Choose a reference frame: positions measured relative to the classroom floor.','Choose an origin: the door is x = 0 m.','Choose a positive direction: right is positive.','A desk at x = −2 m lies 2 m left of the door.'),'Have each student draw the origin and label the positive arrow. Negative position describes a location, not a direction of motion. A person at −2 m can walk either way.'),
S('Two ways to describe the same route',table(['Quantity','How to find it','Direction?'],[['Position x','Location relative to an origin','Signed coordinate'],['Distance','Add the length of every leg','No'],['Displacement Δx','Final position minus initial position','Yes']]),eq('Δx = x<sub>f</sub> − x<sub>i</sub>'),'Explain delta as “change in.” The subscripts label final and initial values. Distance cannot be negative. A one-dimensional displacement uses a sign after the positive direction is defined.'),
S('Worked route: out and back',p('Start at 0 m, walk to 4 m, then return to 1 m.'),eq('Distance = |4 − 0| + |1 − 4| = 7 m'),eq('Displacement = 1 − 0 = +1 m'),'Physically walk the route. Pause at the turn and ask whether returning subtracts from the path already traveled. It changes displacement, but the traveled distance continues increasing.',{tag:'Worked example'}),
S('Route comparison',sim('route'),'Set Start 0, Turn 4, Finish 1. Students predict both outputs before revealing. Compare a route ending at 0 with the same turn. Then change the origin by adding 2 to all three positions: both distance and displacement stay the same.',{tag:'Predict, change, explain'}),
Q('Guided route',p('Start at 2 m, walk to 6 m, then finish at 3 m.','Sketch the route. Calculate both distance and displacement.'),p('Distance = |6 − 2| + |3 − 6| = 4 + 3 = <strong>7 m</strong>.','Displacement = 3 − 2 = <strong>+1 m</strong>. Position 3 m and displacement +1 m are different quantities.'),'Ask students to name the two endpoints used in the displacement calculation. If they answer 3 m, they have treated the final position as a change.'),
S('Scalar and vector quantities',p('A <strong>scalar</strong> has magnitude and units. Distance 7 m and elapsed time 5 s are examples.','A <strong>vector</strong> also has direction. Displacement +1 m means 1 m in the chosen positive direction.','In two dimensions, an arrow or a magnitude with an angle can specify the direction.'),'Use ordinary language first: how much versus how much and which way. “Negative scalar” can exist for some quantities, so do not define every scalar as positive. Distance and elapsed time are nonnegative.'),
Q('Changing the positive direction',p('A person moves 3 m east. First choose east as positive, then choose west as positive.','What changes in the description? What stays the same physically?'),p('The displacement is <strong>+3 m</strong> with east positive and <strong>−3 m</strong> with west positive. The actual motion and 3 m distance do not change.'),'This exposes the misconception that negative means bad or smaller movement. Ask students to write the axis convention beside both answers.'),
Q('Independent routes',table(['Route','Find distance and displacement'],[['A','−2 m to +3 m to −1 m'],['B','+5 m to +5 m with no movement'],['C','One complete 400 m track lap']]),p('A: distance 5 + 4 = <strong>9 m</strong>, displacement <strong>+1 m</strong>.','B: both <strong>0 m</strong>. C: distance <strong>400 m</strong>, displacement <strong>0 m</strong>.'),'For C, state that the runner returns to the exact starting point. For B, distinguish remaining in place from making an unreported trip: the prompt specifies no movement.',{tag:'Independent practice'}),
Q('Why direction matters in the asteroid story',p('Two objects each travel 1,000 km. One moves toward Earth and one moves across our line of sight. Can distance alone tell us their future positions?'),p('No. Equal distance can lead to different endpoints. We need the starting position and a displacement vector with direction to predict each endpoint.'),'Keep collision claims out of this lesson. Moving toward Earth at one instant does not establish collision because both objects and their velocities can change.')
], 'Start at −3 m, move to +2 m, and finish at −1 m. Find distance and displacement, with units.','Distance = 5 + 3 = 8 m. Displacement = −1 − (−3) = +2 m.','If a student subtracts route legs for distance, physically retrace the path and count cumulative meters.');
L(3,'Velocity and position–time graphs','Calculate average velocity and interpret a position–time graph using slope.','Motion detector and graphing software, clear walking lane. Online: supplied data and interactive model.','5 min retrieve • 12 min explain • 15 min walk lab • 12 min practice • 3 min discuss • 3 min exit',[
Q('Same trip, different rates',p('Two walkers each move +12 m. Walker A takes 6 s and Walker B takes 4 s. Who has the greater average velocity? Show the comparison.'),p('A: 12/6 = <strong>+2 m/s</strong>. B: 12/4 = <strong>+3 m/s</strong>. B changes position more per second.'),'Ask for units before comparing numbers. “B is faster” is incomplete evidence without the rate calculation.'),
S('Average velocity and average speed',eq('v̄ = Δx / Δt'),eq('Average speed = total distance / elapsed time'),p('Average velocity carries direction. Average speed describes path length covered per second.','An instantaneous velocity describes a particular moment. An average summarizes an interval.'),'Use a return trip to show that average speed can be positive while average velocity is zero. Do not equate average speed with the magnitude of average velocity for a route that reverses.'),
Q('Round-trip rates',p('A student walks 6 m east and 6 m west in 8 s total. Find average speed and average velocity.'),p('Distance = 12 m, so average speed = 12/8 = <strong>1.5 m/s</strong>.','Displacement = 0 m, so average velocity = 0/8 = <strong>0 m/s</strong>.'),'Ask whether zero average velocity means the student stood still. The interval average does not reveal every moment of motion.'),
S('Slope connects a graph to motion',chart('line',[[0,1],[2,5],[4,9]],['Time (s)','Position (m)']),eq('Slope = (9 − 1) m / (4 − 0) s = +2 m/s'),'Read the axes before calculating. The vertical coordinate is position, not height above the floor. Use two well-separated points on a fitted straight line for measured data.',{tag:'Worked graph'}),
S('Position is the graph’s height; velocity is its slope',table(['Position–time segment','Motion'],[['Straight, rising line','Constant positive velocity'],['Horizontal line','Position stays constant, v = 0'],['Straight, falling line','Constant negative velocity'],['Curve with changing slope','Velocity changes']]),'Compare two parallel lines at different heights. They show different positions but equal velocities. Ask students to gesture the motion described by each segment.'),
S('Match the graph investigation',list('Clear a walking lane and follow the detector’s minimum-distance guidance.','Start about 1 m from the detector. Predict a graph for walking away steadily.','Record a safe walking trial. Repeat for standing still and walking toward it.','For each trial, sketch the graph and calculate one slope.','Submit three labeled graphs and one sentence connecting slope to motion.'),'Use a spotter and walking speed only. Confirm that the software’s positive direction is away from the detector. If no detector is available, use the next data set and explain that it is practice data, not a measurement made by the student.',{tag:'Investigation 1.1'}),
Q('A walk with a pause',table(['t (s)','0','2','4','6'],[['x (m)','1','5','5','1']])+p('Sketch the position–time graph by connecting successive points. Find the velocity on each interval.'),p('0–2 s: <strong>+2 m/s</strong>. 2–4 s: <strong>0 m/s</strong>. 4–6 s: <strong>−2 m/s</strong>.','The walker moves away, waits, and returns. Sharp corners idealize quick changes in motion.'),'This table is an alternative online investigation. Require a slope triangle for one interval. Do not calculate a single whole-trip slope when asked for segment velocities.'),
S('Changing the motion',sim('motion'),'Use x₀ = 1 m, v₀ = 2 m/s, a = 0. Predict x at 4 s, then scrub time. Change v to −1 m/s while keeping x₀ and a fixed. Ask what changes in the position graph. The model is a mathematical motion display, not collected detector data.',{tag:'Model comparison'}),
Q('A graph-reading error',p('Mia says, “The point at x = 8 m means the velocity is 8 m/s.” Explain the error and say what else you need.'),p('The point gives <strong>position</strong>. To find an interval velocity, choose a second point and calculate Δx/Δt. For an instantaneous velocity on a curve, inspect the tangent slope.'),'For CPA, accept “look at slope, using two points on a straight section.” Do not require calculus terminology.'),
Q('Independent graph calculation',p('A straight position–time line passes through (2 s, 14 m) and (6 s, 6 m). Find velocity and predict x at 8 s if the line continues.'),p('v = (6 − 14)/(6 − 2) = <strong>−2 m/s</strong>.','Two more seconds change position by −4 m, so x(8 s) = 6 − 4 = <strong>2 m</strong>.'),'If a student divides 6 m by 6 s, ask whether the line starts at the origin. Slope is a ratio of changes, not arbitrary coordinates.')
], 'A straight x–t segment runs from (1 s, 3 m) to (5 s, 11 m). Find its velocity and explain the slope’s units.','(11 − 3)/(5 − 1) = +2 m/s. Position changes by +2 m each second.','If graphs are treated as pictures of the walking path, return to reading each axis aloud.');
L(4,'Velocity–time graphs and components','Read a velocity–time graph and describe a two-dimensional velocity using perpendicular components.','Graph paper, ruler, calculator in degree mode.','5 min retrieve • 12 min graphs • 12 min vectors • 13 min practice • 5 min explain • 3 min exit',[
Q('A horizontal line can mean motion',p('A velocity–time graph stays at +3 m/s for 4 s. Does the object stop? How far does it move?'),p('It moves at a constant velocity. Displacement = (+3 m/s)(4 s) = <strong>+12 m</strong>.'),'Contrast with a horizontal position–time graph. Have students say the vertical-axis quantity before giving an interpretation.'),
S('The axis changes the meaning',table(['Graph','Height tells you','Slope tells you'],[['Position vs. time','Position','Velocity'],['Velocity vs. time','Velocity','Acceleration']]),p('A line below zero on a velocity graph represents negative velocity. It can be perfectly horizontal while the object keeps moving.'),'Acceleration receives full treatment on Day 7. Today, identify whether velocity changes. Require units on every axis.'),
S('Area under a velocity graph',chart('step',[[0,2],[3,2],[3,-1],[5,-1]],['Time (s)','Velocity (m/s)']),p('First 3 s: Δx = +6 m. Next 2 s: Δx = −2 m.','Total displacement = <strong>+4 m</strong>. Total distance = <strong>8 m</strong>.'),'The signed rectangular areas add to displacement. Sum the magnitudes of the two areas for distance. The instantaneous jump is an idealized turn, not a physical infinite-acceleration claim.'),
Q('Reading before calculating',p('An object has v = −4 m/s from 0 to 3 s, then v = 0 from 3 to 5 s. Describe its motion and find total displacement.'),p('It moves in the negative direction for 3 s, then rests for 2 s.','Δx = (−4)(3) + (0)(2) = <strong>−12 m</strong>.'),'Ask whether the last two seconds undo the earlier displacement. Rest leaves position unchanged.'),
S('A velocity vector has two components',p('For a vector in a horizontal plane, choose perpendicular x and y axes.','A velocity of +4 m/s east and +3 m/s north is one diagonal motion with both components occurring at once.'),eq('|v| = √(4² + 3²) = 5 m/s'),'Draw the supplied numeric components on graph paper at one centimeter per m/s. The object does not first move east and then north. Component vectors describe the simultaneous motion.'),
S('The angle needs a reference axis',p('Let θ be measured counterclockwise from the positive x-axis.'),eq('v<sub>x</sub> = v cos θ'),eq('v<sub>y</sub> = v sin θ'),p('Adjacent component uses cosine. Opposite component uses sine. Use degree mode for an angle in degrees.'),'Point to the angle on a student’s sketch. If the angle is given from the y-axis, the adjacent component is y. Do not teach “x always cosine” without naming the reference axis.'),
S('A clearly defined asteroid vector',p('Teaching convention: +x points from the initial asteroid position toward Earth. +y is perpendicular in the diagram plane. The velocity points 15° from +x toward +y.'),eq('v<sub>x</sub> = 8,500 cos 15° ≈ +8,210 m/s'),eq('v<sub>y</sub> = 8,500 sin 15° ≈ +2,200 m/s'),'State that these are fictional scenario values. “15 degrees toward Earth” alone is ambiguous, so define the reference axis explicitly. Here x is initially Earthward, a fixed direction for the toy model.',{tag:'Worked example'}),
Q('Guided components',p('A drone moves at 10 m/s, 30° north of east. Let east be +x and north be +y. Find both components and say which is larger.'),p('vₓ = 10 cos 30° ≈ <strong>+8.66 m/s</strong>. vᵧ = 10 sin 30° = <strong>+5.00 m/s</strong>.','The vector lies closer to east, so the east component should be larger.'),'Use the size comparison as a reasonableness check before calculator work. Permit measured graphical components as a first pass.'),
Q('Independent components',p('A second drone moves at 12 m/s, 60° north of east. Find the components. Explain why you do not add them to find the speed.'),p('vₓ = <strong>+6.00 m/s</strong>, vᵧ ≈ <strong>+10.39 m/s</strong>.','Perpendicular components form a right triangle. √(6² + 10.39²) ≈ 12 m/s. Their ordinary sum is not the vector’s magnitude.'),'Look for one consistent scale and labeled directions. Two components can each be smaller than the magnitude while their arithmetic sum exceeds it.'),
Q('A better position prediction',p('If the asteroid has a sideways velocity component, can an Earthward displacement alone locate it after a month? Explain what is missing.'),p('We need the sideways displacement as well. Predict x and y using their own velocity components over the same elapsed time.'),'This prepares Day 5. Avoid saying the Earthward component determines a collision independently of the perpendicular component and Earth’s motion.')
], 'On a v–t graph, v = +2 m/s for 5 s. Find displacement. Then state what information must accompany an angle used to split a vector.','Δx = +10 m. The angle’s reference axis and sense/direction must be stated.','If a horizontal v–t line is read as rest, compare it beside a horizontal x–t line before proceeding.');
L(5,'Position predictions and uncertainty','Predict position with consistent units and explain how measurement bounds grow with time.','Calculator, graph paper. All asteroid values are fictional.','5 min retrieve • 12 min model • 13 min worked case • 12 min uncertainty • 5 min transfer • 3 min exit',[
Q('Units before multiplication',p('A train travels at 40 m/s for 2 hours. Find its displacement if velocity stays constant.'),p('2 h × 3,600 s/h = 7,200 s.','Δx = (40 m/s)(7,200 s) = <strong>288,000 m = 288 km</strong>.'),'Ask students to cancel the hours explicitly. 40 × 2 has no useful distance meaning until the time units agree.'),
S('Position includes the starting point',eq('x<sub>f</sub> = x<sub>0</sub> + v<sub>x</sub>t'),p('For constant velocity, displacement is vₓt. The initial position can be nonzero.','In two dimensions, also use y<sub>f</sub> = y<sub>0</sub> + v<sub>y</sub>t.'),'Use the distinction between position and displacement from Day 2. State that t means elapsed time here. These equations presume constant velocity in the chosen frame.'),
Q('A local prediction',p('A cart starts at x₀ = 12 m and moves at −2 m/s for 4 s. Find displacement and final position.'),p('Δx = (−2)(4) = <strong>−8 m</strong>.','x<sub>f</sub> = 12 + (−8) = <strong>4 m</strong>.'),'Students should sketch the start at 12 and the endpoint at 4. A negative displacement does not require a negative final position.'),
S('Coordinates for the asteroid model',p('Put Earth at (0, 0) and the asteroid initially at (−1.2 × 10⁸ km, 0). Define +x toward Earth from that initial position.','Use v = 8.5 km/s at 15° above +x. Let six months mean <strong>1.6 × 10⁷ s</strong> in this task.','Freeze Earth at the origin and hold velocity constant. These are deliberate simplifications.'),'The frame is an Earth-fixed geometric toy model, not a valid inertial orbital forecast over six months. Do not make a real impact claim. The class needs the simplification stated before computing.',{tag:'Fictional model assumptions'}),
S('Worked two-dimensional prediction',eq('v<sub>x</sub> ≈ 8.210 km/s, v<sub>y</sub> ≈ 2.200 km/s'),eq('x<sub>f</sub> = −1.20 × 10⁸ + 8.210(1.6 × 10⁷)'),p('<strong>x<sub>f</sub> ≈ +1.14 × 10⁷ km</strong> and <strong>y<sub>f</sub> ≈ +3.52 × 10⁷ km</strong>.','Distance from the fixed origin ≈ √(x<sub>f</sub>² + y<sub>f</sub>²) ≈ <strong>3.70 × 10⁷ km</strong>.'),'Keep more digits in the calculator until the end. Positive final x means the path has passed the origin’s perpendicular line, not that the object hit Earth. The y offset is large. This corrects the source plan’s unsupported 0.9 × 10⁸ km result.'),
Q('Position and displacement are different vectors',p('The model travels about 1.36 × 10⁸ km in six months. Why is that different from the final 3.70 × 10⁷ km separation from Earth?'),p('Travel distance describes the path covered. Final separation measures the endpoint from Earth’s origin. The asteroid began far from that origin and moved diagonally past its x-coordinate.'),'Ask students to identify which arrow starts at the initial asteroid and which starts at Earth. Equal-looking units do not imply the quantities are interchangeable.'),
S('A measurement interval is a bound',p('A position written 100 ± 2 m means values from 98 to 102 m under the stated bound.','For x = x₀ + vt with t ≥ 0, independent bounded one-dimensional inputs give:'),eq('δx<sub>f</sub> = δx<sub>0</sub> + t δv'),p('This is a conservative bound, not automatically a confidence interval.'),'Use δ for the uncertainty half-width and Δ for change. We use worst-case interval addition, not statistical quadrature. A speed uncertainty and a directional uncertainty are different inputs.'),
Q('Guided uncertainty',p('A cart starts at 10 ± 1 m and moves at 2.0 ± 0.2 m/s for exactly 5 s. Find the central prediction, its bound, and the full width.'),p('Central x = 10 + 2(5) = <strong>20 m</strong>.','Half-width = 1 + 5(0.2) = <strong>2 m</strong>. Interval <strong>18–22 m</strong>, full width <strong>4 m</strong>.'),'Have students compute both extreme endpoints directly once: 9 + 1.8(5) and 11 + 2.2(5). This gives meaning to the formula.'),
S('The asteroid’s simplified bounds',p('Treat the speed bound as ±0.2 km/s at a fixed 15° angle, with initial x bound ±50,000 km and y₀ exact in this teaching model.'),eq('δx ≈ 50,000 + t(0.2 cos 15°) ≈ 3.14 × 10⁶ km'),eq('δy ≈ t(0.2 sin 15°) ≈ 8.28 × 10⁵ km'),'These are coordinate bounds, not independent x/y speed errors. The same speed parameter drives both coordinates, so they are correlated. Angular error, time error, and model error are excluded. Do not label the box a probability contour.'),
S('Graphing a widening prediction band',chart('band',[[0,10,9,11],[2,14,12.6,15.4],[5,20,18,22]],['Time (s)','Position (m)']),p('The central line gives the expected position. The upper and lower lines use the extreme inputs. The band widens because velocity uncertainty accumulates over time.'),'Use the cart example, not an enormous-scale graph, to teach the geometry. Students should label central, upper, and lower predictions and distinguish half-width from full width.'),
Q('Model error is another uncertainty',p('Suppose velocity changes because of gravity. Would narrower position and speed measurement bounds make the constant-velocity prediction exact?'),p('No. Better measurements reduce input uncertainty. They do not remove error from an unsuitable constant-velocity model. Gravity and Earth’s motion matter for an actual long-term orbit prediction.'),'Do not justify a six-month model solely with “acceleration is small.” Its accumulated effect depends on time. This limitation is part of a strong public briefing.'),
Q('Independent prediction',p('An object starts at 30 ± 2 m with velocity −3.0 ± 0.1 m/s. Predict x after 10 s and give the full uncertainty interval.'),p('Central x = 30 − 30 = <strong>0 m</strong>. Half-width = 2 + 10(0.1) = <strong>3 m</strong>.','Interval <strong>−3 to +3 m</strong>, full width <strong>6 m</strong>.'),'A range crossing zero is legitimate. Require the student to explain what zero means in the coordinate system.')
], 'At x₀ = 4 ± 1 m, v = 2 ± 0.5 m/s, and t = 4 s, give the central position and interval. Name one excluded model effect.','12 m with half-width 3 m: 9–15 m. A changing velocity or unmodeled force is an excluded effect.','If uncertainty is treated as a mistake, repeat endpoint calculations and distinguish a bound from arithmetic error.');
L(6,'Adding and resolving vectors','Add vectors by components and use an angle’s reference axis to choose sine or cosine.','Graph paper, ruler, protractor, calculator in degree mode.','5 min retrieve • 12 min model • 10 min components • 15 min practice • 5 min check • 3 min exit',[
Q('Distance around a corner',p('Walk 4 m east and then 3 m north. Find path distance and straight-line displacement magnitude.'),p('Distance = <strong>7 m</strong>. Displacement magnitude = √(4² + 3²) = <strong>5 m</strong>, directed northeast.'),'Have students draw before calculating. “Northeast” describes the quadrant, while the precise direction is 36.9° north of east.'),
S('Tip-to-tail addition',list('Draw the first vector to a chosen scale.','Translate the second vector so its tail meets the first tip. Preserve its length and direction.','Draw the resultant from the first tail to the final tip.','Label magnitude, direction, and units.'),'Use students’ 4 m and 3 m drawings. Rotating a vector changes the vector. Sliding it without rotating is allowed in this addition construction.'),
S('Components add along matching axes',eq('R<sub>x</sub> = A<sub>x</sub> + B<sub>x</sub>'),eq('R<sub>y</sub> = A<sub>y</sub> + B<sub>y</sub>'),p('Then |R| = √(Rₓ² + Rᵧ²). Find direction from the signs and the component ratio.'),'Separate the component addition from the magnitude calculation. Do not add perpendicular component magnitudes as ordinary numbers to get the resultant magnitude.'),
S('Worked addition with signs',p('A = (+6, +2) m and B = (−4, +3) m.'),eq('R = (+2, +5) m'),eq('|R| = √(2² + 5²) ≈ 5.39 m'),p('θ = tan⁻¹(5/2) ≈ 68.2° north of east.'),'Both resultant components are positive, so the angle lies in the first quadrant. Explain that an inverse tangent of a ratio alone can give the wrong quadrant when signs differ.'),
Q('Guided addition',p('A = (+3, −2) m and B = (−7, +5) m. Find the resultant components, magnitude, and compass direction.'),p('R = <strong>(−4, +3) m</strong>, |R| = <strong>5 m</strong>.','Direction = <strong>36.9° north of west</strong>, or 143.1° counterclockwise from east.'),'Start with the sketch: left and up. A calculator value of −36.9° without correcting the quadrant describes the wrong direction.'),
S('Decomposition from a stated angle',p('A 20 N pull points 30° above the positive x-axis.'),eq('F<sub>x</sub> = 20 cos 30° ≈ 17.3 N'),eq('F<sub>y</sub> = 20 sin 30° = 10.0 N'),p('The components together represent the original force. They are not two extra forces.'),'If students draw the original vector and both components, use dashed component guides to avoid implying three separate forces act.'),
Q('The same angle measured from another axis',p('A 20 N pull points 30° east of north. Let east be +x. Find the components.'),p('The angle is next to the y component. Fᵧ = 20 cos 30° ≈ <strong>17.3 N</strong>.','Fₓ = 20 sin 30° = <strong>10.0 N</strong>.'),'Have learners circle the words “east of north.” The reference direction is north, so this reverses the earlier component sizes.'),
Q('Three independent checks',list('Add 8 m east and 6 m west.','Resolve 10 m/s at 40° south of east.','Add (+2, +4) m to (−2, −4) m. What is the resultant direction?'),p('1. <strong>+2 m east</strong>. 2. <strong>(+7.66, −6.43) m/s</strong>.','3. <strong>(0, 0) m</strong>. The zero vector has no defined direction.'),'Use these as a short diagnostic: signs, reference angle, and zero-vector reasoning. A vector with zero magnitude must not receive an arbitrary compass direction.',{tag:'Independent practice'}),
Q('Reconstructing the asteroid velocity',p('A fictional velocity has components about +8,210 m/s and +2,200 m/s. Reconstruct its magnitude and angle from +x.'),p('Magnitude ≈ √(8,210² + 2,200²) ≈ <strong>8,500 m/s</strong>.','θ = tan⁻¹(2,200/8,210) ≈ <strong>15°</strong>. Small differences come from rounded components.'),'Ask why the reconstructed result need not equal 8,500 exactly when the inputs were rounded. Rounding error is different from a measurement uncertainty interval.')
], 'Resolve a 10 N vector 30° west of north. Use east as +x and north as +y.','Fₓ = −5.0 N, Fᵧ ≈ +8.66 N.','If cosine/sine swap, redraw the reference angle and identify the adjacent component before using the calculator.');
L(7,'Acceleration and changing velocity','Use velocity change to calculate acceleration and distinguish acceleration direction from speeding up.','Calculator, graph paper, motion model.','5 min retrieve • 12 min explanation • 10 min graphs • 15 min practice • 5 min limits • 3 min exit',[
Q('A rate of change of a rate',p('A cart’s velocity changes from +2 to +8 m/s in 3 s. How much does its velocity change each second, on average?'),p('Δv = +6 m/s. ā = (+6 m/s)/(3 s) = <strong>+2 m/s²</strong>.'),'Say “two meters per second of velocity added each second.” This interprets the compound units without treating seconds squared as a mysterious extra number.'),
S('Acceleration measures velocity change',eq('ā = (v<sub>f</sub> − v<sub>i</sub>) / Δt'),p('Velocity can change in magnitude, direction, or both.','Speeding up, slowing down, and turning can all involve acceleration.'),'A car turning at constant speed has a changing velocity vector. Keep the current calculations one-dimensional, but do not define acceleration as only a speed increase.'),
S('Signs describe directions',table(['v','a','Speed trend'],[['Positive','Positive','Increases'],['Positive','Negative','Decreases until v = 0'],['Negative','Negative','Increases'],['Negative','Positive','Decreases until v = 0']]),'Use right/left gestures for the chosen axis. Opposite signs mean slowing at that instant. If the acceleration continues through v = 0, the object reverses and then speeds up.'),
Q('Braking in the positive direction',p('A car travels at +30 m/s and stops in 5 s. Find its average acceleration.'),eq('a = (0 − 30)/5 = −6 m/s²')+p('The acceleration points opposite the positive velocity, so the car slows down.'),'Require the subtraction before division. The source phrase “slowing down has negative acceleration” is true only for a positive initial velocity.'),
Q('Braking in the negative direction',p('A cart moves at −12 m/s, then reaches −4 m/s after 2 s. Find acceleration. Is the cart speeding up?'),p('a = [−4 − (−12)]/2 = <strong>+4 m/s²</strong>.','Speed falls from 12 to 4 m/s. The positive acceleration slows the negative motion.'),'Ask for both velocity and speed values. This separates sign from magnitude and counters the most common misconception.'),
S('The slope of a velocity–time graph',chart('line',[[0,-4],[2,0],[4,4]],['Time (s)','Velocity (m/s)']),eq('a = [4 − (−4)] / 4 = +2 m/s²'),p('The object slows for the first 2 s, stops momentarily, then speeds up in the positive direction.'),'The line crosses v = 0, but its slope stays positive. Ask students where the direction reverses and where the acceleration becomes zero. It never becomes zero on this line.'),
S('One clock, linked representations',sim('motion'),'Set x₀ = 0, v₀ = −4, a = +2. Scrub to t = 1, 2, and 3 s. Students record the sign of velocity and whether position is increasing. The position curve has a turning point at 2 s, while acceleration stays +2.',{tag:'Model investigation'}),
S('Constant acceleration is an assumption',eq('v = v₀ + at'),eq('x = x₀ + v₀t + ½at²'),p('These equations apply over an interval with constant acceleration.','If acceleration varies significantly, one constant value may not describe the whole interval.'),'Use a straight velocity–time line as evidence of constant acceleration. Real brakes, engines, and gravitational fields do not always produce an exactly constant value.'),
Q('A small acceleration over a long time',p('Hypothetical constant a = 0.001 m/s² acts for 1.6 × 10⁷ s. Calculate Δv. Is the small acceleration number alone enough to justify ignoring it?'),p('Δv = at = <strong>16,000 m/s</strong>.','No. The accumulated change depends on time. This is a hypothetical bound check, not the actual acceleration of 2026-XJ.'),'This corrects the original six-month justification. “Less than 0.001” is too loose by itself to establish negligible velocity change. Do not infer a real orbital acceleration from this exercise.'),
Q('Independent interval analysis',p('Velocity changes from −3 to −9 m/s in 2 s. Then it stays at −9 m/s for 4 s. Find acceleration in each interval and describe the speed trend.'),p('First interval: <strong>−3 m/s²</strong>, speeding up. Second: <strong>0 m/s²</strong>, constant speed 9 m/s.'),'Check that the learner does not treat a negative velocity as a negative acceleration automatically.')
], 'An object goes from −6 to 0 m/s in 3 s. Find acceleration and explain whether speed increases or decreases.','+2 m/s². Speed decreases from 6 m/s to zero because acceleration and velocity have opposite directions.','If the sign explanation fails, reteach with left/right velocity arrows before more equations.');
L(8,'Choosing a motion equation','Select a constant-acceleration equation from known quantities and justify a physically meaningful result.','Calculator, equation reference, paper.','5 min retrieve • 12 min worked example • 10 min second case • 17 min practice • 3 min compare • 3 min exit',[
Q('A quick retrieval',p('A skateboarder speeds up from +2 to +5 m/s in 2 s. Find average acceleration.'),p('a = (5 − 2)/2 = <strong>+1.5 m/s²</strong>.'),'If the result is 2.5, ask which initial velocity was omitted.'),
S('Three equations, one model',table(['Equation','Useful when…'],[['v = v₀ + at','You need velocity or time'],['Δx = v₀t + ½at²','You know elapsed time'],['v² = v₀² + 2aΔx','Time is not given or needed']]),p('All three assume constant acceleration over the interval. Define the axis before assigning signs.'),'These are options, not a rule to memorize by keyword. Ask which quantities each equation connects and whether it introduces an unnecessary unknown.'),
S('A repeatable solution structure',list('Sketch the motion and choose a positive direction.','List known quantities with units and signs. Name the unknown.','Choose an equation containing those quantities.','Rearrange, substitute, and calculate.','Check units, sign, and physical meaning.'),'Model the thought process aloud. Keep the equation reference visible. Formula recall alone is not the target.'),
Q('Worked braking distance',p('A car moves at +20 m/s and brakes at constant −4 m/s² until it stops. How far does it travel?'),eq('0² = 20² + 2(−4)Δx')+eq('Δx = −400 / (−8) = +50 m')+p('Time is unnecessary. As a check, t = 5 s and average velocity = 10 m/s, giving 50 m.'),'Unpack why v is zero but displacement is not. The positive displacement is consistent with traveling forward while braking.',{tag:'Worked example'}),
Q('Worked final position',p('A cart starts at x₀ = −3 m with v₀ = +2 m/s. It accelerates at +1 m/s² for 4 s. Find its final position.'),eq('Δx = 2(4) + ½(1)(4²) = 16 m')+eq('x = −3 + 16 = +13 m'),'Distinguish x from Δx. Students often correctly compute 16 m and mislabel it as final position.'),
Q('Guided launch from rest',p('A train starts at rest and accelerates uniformly at 0.50 m/s². How long does it take to reach 12 m/s? How far does it travel during that time?'),p('t = (12 − 0)/0.50 = <strong>24 s</strong>.','Δx = ½(0.50)(24²) = <strong>144 m</strong>.'),'Let students solve the second part using either displacement equation or average velocity times time. Ask them to explain why (v₀+v)/2 works here: acceleration is constant.'),
Q('Vertical motion uses the same tools',p('A ball launches upward at 14 m/s. Ignore air resistance and use upward as positive, a = −9.8 m/s². Find the rise to its highest point.'),p('At the highest point v = 0.','0 = 14² + 2(−9.8)Δy, so Δy = <strong>10 m</strong>. Acceleration is still downward at the top.'),'A zero instantaneous velocity does not imply zero acceleration. The ball’s height above the ground also requires its initial height.'),
Q('Independent practice set A',list('A cart has v₀ = 3 m/s and a = 2 m/s² for 4 s. Find v and Δx.','A bicycle brakes from 10 m/s to rest at −2.5 m/s². Find stopping time and distance.'),p('1. v = <strong>11 m/s</strong>, Δx = 12 + 16 = <strong>28 m</strong>.','2. t = <strong>4 s</strong>, Δx = <strong>20 m</strong>.'),'Collect the chosen equation before the arithmetic. If a student uses v·t with the final velocity, compare the result with average velocity.'),
Q('Independent practice set B',list('An object starts at x₀ = 8 m, v₀ = −2 m/s, a = −1 m/s². Find x after 3 s.','A cart starts from rest and reaches 6 m/s after 9 m of constant acceleration. Find a.'),p('1. x = 8 − 6 − 4.5 = <strong>−2.5 m</strong>.','2. 36 = 2a(9), so a = <strong>2 m/s²</strong>.'),'The first object moves into the negative side of the axis. Require both position and displacement if the learner seems to conflate them.'),
Q('Error analysis: beyond the stopping point',p('A car starts at +12 m/s with a = −3 m/s². A student uses the same acceleration for 8 s and concludes v = −12 m/s. What assumption needs checking?'),p('The car reaches rest after 4 s. The 8 s answer is valid only if the same acceleration continues and makes the car reverse. Ordinary “braking to a stop” ends the model interval at 4 s.'),'Do not label the algebra wrong. The issue is applying the model beyond its stated physical interval.')
], 'A cart moves at +4 m/s and accelerates at +2 m/s² for 3 s. Find displacement and name the assumption.','Δx = 4(3) + ½(2)(9) = 21 m. Acceleration stays constant for the 3 s interval.','If equation choice is random, require the known/unknown list before permitting calculator entry.');
L(9,'Inertia and Newton’s first law','Predict motion from zero net force and explain why continued motion does not require a continued push.','Low-friction cart, level track, soft stop. Online model and scenarios.','5 min retrieve • 10 min prediction • 12 min demo • 15 min explanation/practice • 5 min apply • 3 min exit',[
Q('After the hand lets go',p('You give a cart a short push on a smooth level track. After your hand loses contact, what happens to the force from your hand? What happens to the cart’s motion?'),p('The contact force from the hand ends. The cart can keep moving. Small resistive forces may gradually slow it.'),'Separate the push interval from the coast interval. Avoid saying real tracks have literally zero friction.'),
S('Newton’s first law',p('In an inertial reference frame, an object at rest stays at rest, and an object in motion keeps the same velocity, unless a nonzero net external force changes that velocity.'),eq('ΣF = 0  implies  a = 0'),'Explain net as the vector sum of external forces. Zero net force can mean several balanced forces or no forces. It does not uniquely determine whether v is zero.'),
S('Inertia and mass',p('<strong>Inertia</strong> is resistance to a change in velocity. Mass measures translational inertia.','With the same net force, a larger mass changes velocity more slowly.','Inertia is a property of the object, not an extra force arrow.'),'Use an empty and loaded cart qualitatively. Save numerical F=ma work for later. Never draw an “inertia force” on an ordinary inertial-frame free-body diagram.'),
S('A controlled cart demonstration',list('Predict how far a cart coasts on two level surfaces after a comparable release.','Use a gentle release and a soft stop. Keep people clear of the track.','Observe how quickly velocity changes after contact with the hand ends.','Explain the slowing using interactions with the surface and air.'),'Equal hand pushes are difficult to reproduce. Use a repeatable release if available and avoid claiming a quantitatively controlled experiment when pushes differ. Online learners compare the ideal zero-net-force case to a small resisting force.',{tag:'Predict, observe, explain'}),
Q('A moving object with balanced forces',p('A box slides right at constant velocity while a rope pulls it with 8 N right and friction acts with 8 N left. What is the net horizontal force?'),p('ΣFₓ = +8 − 8 = <strong>0 N</strong>. The box keeps a constant velocity because acceleration is zero.'),'Ask whether “constant” means “fast” or “slow.” The forces determine change in velocity, not its existing value.'),
Q('The passenger explanation',p('A bus brakes suddenly. A passenger’s body moves forward relative to the bus. Explain without adding a mysterious forward force.'),p('The passenger initially shares the bus’s forward velocity. As the bus slows, the body tends to continue moving. A seat belt, seat, or other contact supplies a force that changes the passenger’s velocity.'),'The body’s forward motion is inertia, not a new forward push. Discuss restraint function at a conceptual level without staging a risky demo.'),
Q('Evidence of a net force',list('A cart at rest remains at rest.','A cart moves straight at steady speed.','A cart turns at steady speed.','A cart slows while moving straight.'),p('The first two can have <strong>zero net force</strong>. Turning and slowing require a velocity change, so the net force is <strong>nonzero</strong>.'),'Use “can” for the first case only if the interval is truly unchanged. In these specified constant motions, acceleration and net force are zero.'),
Q('The asteroid connection',p('In an ideal region with zero net force, would an asteroid need an engine to keep moving? What must change for a deflection?'),p('It would keep constant velocity without an engine. A deflection requires a change in velocity, produced by a nonzero net external force.','Real asteroids experience gravity, so their paths generally curve.'),'No air resistance does not mean no force. Distinguish the ideal first-law thought experiment from the actual solar system.')
], 'A spacecraft moves straight at constant velocity with engines off. State its net force in the ideal model and predict its motion 10 s later.','Net force is zero. It keeps the same velocity, so its displacement is velocity multiplied by 10 s.','If students insist motion requires a push, compare the push and coast intervals explicitly.');
L(10,'Identifying forces and interactions','Identify external forces by naming the object exerting each force and the object receiving it.','Everyday objects, string, notebook, calculator.','5 min retrieve • 12 min force types • 10 min worked examples • 15 min practice • 5 min discuss • 3 min exit',[
Q('Forces on a seated student',p('While you sit still, identify two main vertical forces acting on your body. Name their sources.'),p('Earth exerts weight downward. The chair and floor contacts provide support forces upward. Their vertical total balances weight in this stationary case.'),'Students may name the desk or feet as extra contacts. Accept physically present contacts. Ask “which object exerts that force?” for every suggestion.'),
S('A force describes an interaction',p('Use the naming pattern <strong>force by agent on object</strong>.','“Rope on cart” and “Earth on cart” identify physical interactions.','Motion, speed, acceleration, and inertia are not additional force types.'),'Keep a chosen object visible through each example. An interaction can exist without motion. A wall can push on a stationary object.'),
S('Common external forces',table(['Force','Source and direction'],[['Weight Fg','Earth’s gravity, toward Earth’s center'],['Normal N','Surface, perpendicular to the surface'],['Friction f','Surface, along it, opposing relative slip or its tendency'],['Tension T','Taut string or rope, along it away from the object'],['Applied force','A named hand, tool, or other external agent']]),'Point out that normal means perpendicular, not usual. Friction can act in the direction of an object’s overall motion, as when the ground pushes a walking person forward.'),
S('Mass and weight',eq('F<sub>g</sub> = mg'),p('Mass measures inertia in kilograms. Weight is a gravitational force in newtons.','Near Earth’s surface, use g = 9.8 m/s² unless a problem supplies another value.'),eq('A 5 kg object has weight ≈ 49 N'),'Do not call 5 kg a force. A scale may report a mass-equivalent reading, but the contact interaction it senses is a force.'),
Q('Book on a table',p('Choose the book as the object. Name its vertical forces and their directions. Is the book’s push on the table a force on the book?'),p('Earth on book: weight downward. Table on book: normal upward.','The book’s force on the table acts on the table, so it does not belong in the book’s force list.'),'This establishes the object boundary needed for free-body diagrams and third-law pairs later.'),
Q('A hanging object',p('A 2 kg mass hangs motionless from one vertical string. Name the forces and calculate the tension.'),p('Weight = (2)(9.8) = <strong>19.6 N down</strong>. With zero acceleration, tension is <strong>19.6 N up</strong>.'),'Tension equals weight only under these conditions. An accelerating hanging mass can have a different tension.'),
Q('A moving object after release',p('A ball has left a person’s hand and travels upward. Ignore air resistance. Which forces act after release?'),p('Only Earth’s gravitational force acts in this model. The hand no longer contacts the ball. The ball can move upward while its acceleration points downward.'),'Look for a leftover “throwing force.” Use first-law reasoning to explain why motion continues after the push ends.'),
Q('A surface tilted at an angle',p('A box rests on a rough ramp. Name the directions of weight, normal force, and the static friction that prevents downward slipping.'),p('Weight points vertically downward. Normal points perpendicular away from the ramp. Static friction points up the ramp in this case.'),'Do not say normal always points up. Friction opposes the tendency to slide down, not gravity in every direction.'),
Q('Independent force inventory',list('A box slides right while a rope pulls right across a rough horizontal floor.','A car coasts down a hill with air resistance.','An asteroid moves through deep space.'),p('Box: weight, normal, rightward tension, leftward kinetic friction.','Car: weight, road normal, drag and any road contact forces required by the model. Asteroid: gravitational forces from external bodies.'),'For the car, do not automatically label tire friction as uphill without specifying wheel behavior. A simplified particle model may give a single measured resistance uphill. The ambiguity itself makes a good modeling discussion.')
], 'A 3 kg object hangs still from a string. Name both forces, their agents, magnitudes, and directions.','Earth on object: 29.4 N downward. String on object: 29.4 N upward.','If forces lack agents or include motion, use the sentence “___ pushes/pulls ___” before drawing any arrow.');
L(11,'Cart lab: varying system mass','Use controlled data to test how acceleration depends on total moving mass at nearly constant external driving force.','Cart, level track, low-friction pulley, string, hanging mass, added masses, motion sensor, soft catch. Online: supplied model data.','5 min predict • 10 min setup • 20 min collect • 10 min analyze • 2 min claim • 3 min exit',[
Q('Same driving force, different mass',p('Two systems experience the same net force. One has twice the mass of the other. Predict how their accelerations compare and explain your reasoning.'),p('The system with twice the mass has half the acceleration, if the net force truly stays the same. Greater inertia means less velocity change per second.'),'Record initial predictions without grading correctness. Return to them after graphing. Do not present the answer before students collect or inspect data.',{deferAnswer:true}),
S('The system includes the hanging mass',p('Choose the cart plus hanging mass as the moving system. Let M = cart mass + added masses + hanging mass.','The hanger’s weight mₕg drives the coupled motion. The string tension acts internally between the two parts.'),eq('mₕg − resistance ≈ Ma'),'A fixed hanging mass does not produce a perfectly fixed tension on the cart. Using the full system removes this confusion. Assume a light taut string, negligible pulley inertia, equal acceleration magnitudes, and a level cart track.'),
S('Variables and controls',table(['Role','Quantity'],[['Change','Total moving mass M, by adding mass to cart'],['Measure','Acceleration from the velocity–time slope'],['Keep fixed','Hanging mass, track angle, release position, apparatus'],['Monitor','Resistance, sensor quality, pulley motion']]),'We hold the driving weight constant. The actual net force may vary slightly with resistance. Students should describe the approximation rather than claim perfect control.'),
S('Procedure and safe release',list('Measure cart and hanger masses in kg. Secure added masses. Level the track.','Leave space for the hanger to fall and a soft stop before the cart reaches the pulley.','Release without pushing. Fit a straight section of v–t data while the hanger is still falling.','Repeat three times for each of at least three total masses.','Record all trials and note failed releases separately.'),'Assign release, catch, sensor, and recorder roles. Keep hands out of moving pulley/string paths. Do not fit the initial release transient or the time after the hanger hits the floor.',{tag:'Investigation 1.2'}),
S('A data table with units',table(['M (kg)','a₁','a₂','a₃','Mean a (m/s²)','1/M (kg⁻¹)'],[['____','____','____','____','____','____'],['____','____','____','____','____','____'],['____','____','____','____','____','____']]),p('Record acceleration trials in m/s². Keep the raw values before rounding the mean.'),'Have students compute one mean together using their actual trials. If trials disagree, investigate the release, friction, fit interval, or sensor obstruction. Never remove a result merely because it is inconvenient.'),
Q('From a velocity graph to acceleration',p('During one clean trial, v = 0.10 m/s at 0.20 s and v = 0.40 m/s at 0.80 s. Find the fitted interval’s acceleration.'),p('a = (0.40 − 0.10)/(0.80 − 0.20) = <strong>0.50 m/s²</strong>.'),'Use this as a worked extraction before asking for three trials. Graphing software can fit more than two points, reducing the influence of noise.'),
S('Online alternative: ideal model data',table(['M (kg)','a (m/s²)','1/M (kg⁻¹)'],[['0.50','0.980','2.000'],['0.75','0.653','1.333'],['1.00','0.490','1.000'],['1.50','0.327','0.667']]),p('Model inputs: mₕ = 0.050 kg, g = 9.8 m/s², negligible resistance. These values are calculated, not experimental measurements.'),'Students without apparatus graph this table and evaluate its pattern. Do not let them claim they experimentally verified a law from generated values. Ask what real measurements could test the model.',{tag:'Fallback data'}),
S('The linearized relationship',chart('line',[[0.667,0.327],[1,0.490],[1.333,0.653],[2,0.980]],['1/M (kg⁻¹)','Acceleration (m/s²)']),p('Plot a against 1/M. A straight line through the origin is consistent with a ∝ 1/M.','The ideal slope is about <strong>0.49 N</strong>, the external driving weight.'),'For actual measurements, use a best-fit line and consider a nonzero intercept or scatter. A perfectly linear generated table does not establish experimental precision.'),
Q('A claim supported by numbers',p('Write a claim about mass and acceleration. Support it with two rows of data and explain a control that makes the comparison meaningful.'),p('Example: doubling M from 0.50 to 1.00 kg halves a from 0.980 to 0.490 m/s². The same 0.050 kg hanger keeps the driving weight at 0.49 N in the ideal model.'),'Assess the connection among claim, data, and control. A bare “more mass means less acceleration” misses proportionality.'),
Q('Independent changed case',p('At a fixed net force, a system of mass 0.80 kg accelerates at 0.60 m/s². Predict acceleration for a 1.20 kg system.'),p('Fnet = (0.80)(0.60) = 0.48 N.','a = 0.48/1.20 = <strong>0.40 m/s²</strong>.'),'Require the force condition in the explanation. Tripling mass does not automatically halve acceleration.')
], 'Why should this lab use total cart-plus-hanger mass rather than cart mass alone? What trend supports the claim?','Both masses accelerate. At fixed net external force, acceleration varies inversely with total moving mass.','If the graph looks linear in M rather than 1/M, compare doubling cases and plot the reciprocal mass.');
L(12,'Cart lab: varying driving force','Hold total moving mass constant while testing acceleration versus net driving force.','Same cart apparatus, removable masses, motion sensor. Online: supplied ideal data.','5 min retrieve • 10 min setup • 20 min collect • 10 min analyze • 2 min synthesize • 3 min exit',[
Q('A fair force comparison',p('You increase the hanging mass on yesterday’s rig. If you add new masses from outside the system, what else changes besides driving force?'),p('The total moving mass also increases. That would change two variables at once.'),'Give students time to propose transferring masses already on the cart before showing the corrected method.'),
S('Transfer mass from cart to hanger',p('Keep <strong>M = cart + hanger + all added masses</strong> fixed. Move small masses from the cart to the hanger.','The hanger’s weight changes while the total mass accelerating remains the same.'),eq('a ≈ mₕg / M'),'The whole-system formulation is essential. Tension is not equal to mₕg during acceleration. Track resistance and pulley inertia remain limitations of the simple model.'),
S('Variables and controlled conditions',table(['Role','Quantity'],[['Change','Hanging mass mₕ and driving weight mₕg'],['Hold','Total mass M, track angle, release point, apparatus'],['Measure','Acceleration from a clean v–t interval'],['Repeat','Three trials for each of at least three force settings']]),'Check the total system mass before each force setting. Transferring an existing mass preserves that total, while adding a new mass changes it. Record resistance as a possible confounding effect.'),
S('Collection protocol',list('Weigh the whole moving system and record M in kg.','Begin with a small hanger mass. Release gently and record a.','Transfer mass from cart to hanger, then repeat.','Use the same fitting interval criteria as Day 11.','Record mₕ, Fdrive = mₕg, three accelerations, and their mean.'),'Monitor speeds as hanger mass increases. Use a catch and stop well before the cart reaches the pulley. If the available track is short, reduce the force range.',{tag:'Investigation 1.3'}),
S('Model data for comparison or online work',table(['mₕ (kg)','Fdrive (N)','M (kg)','a (m/s²)'],[['0.025','0.245','1.00','0.245'],['0.050','0.490','1.00','0.490'],['0.075','0.735','1.00','0.735'],['0.100','0.980','1.00','0.980']]),p('These are calculated ideal values with negligible resistance, not measured lab results.'),'Students who have real data compare their trend with this one and explain deviations. Online learners plot and analyze the model table, explicitly labeling it as such.'),
S('Acceleration versus net force',chart('line',[[0.245,0.245],[0.490,0.490],[0.735,0.735],[0.980,0.980]],['Net force (N)','Acceleration (m/s²)']),eq('Slope = Δa / ΔF = 1/M'),'For M = 1.00 kg, slope is 1.00 kg⁻¹. If resistance is significant, using the driving weight as net force overestimates the net force. A fitted intercept can help diagnose that approximation.'),
Q('Reading a slope as mass',p('A graph of a versus Fnet has slope 2.0 (m/s²)/N. What mass does this represent?'),p('Slope = 1/M, so M = 1/2.0 = <strong>0.50 kg</strong>.'),'Ask why the answer is not 2 kg. This is a reciprocal relationship, and the slope units are inverse kilograms.'),
S('Two investigations support one relationship',p('Day 11: at fixed net force, a ∝ 1/M.','Day 12: at fixed mass, a ∝ Fnet.'),eq('ΣF = ma'),p('One newton is the force needed to give 1 kg an acceleration of 1 m/s².'),'Call the results evidence consistent with Newton’s second law. A classroom experiment supports a model within its range and precision; it does not prove a universal law from four points.'),
Q('Force and mass both change',p('System A has Fnet = 2 N and m = 1 kg. System B has Fnet = 6 N and m = 2 kg. Compare their accelerations.'),p('aA = 2/1 = <strong>2 m/s²</strong>. aB = 6/2 = <strong>3 m/s²</strong>.','Tripling force and doubling mass makes acceleration 1.5 times as large.'),'This tests whether students coordinate both variables rather than repeating “more force means more acceleration.”'),
Q('A fictional deflection scale',p('For a teaching model with asteroid mass 3.5 × 10¹¹ kg, find the acceleration caused by a net additional force of 1.0 × 10⁶ N.'),p('a = F/m ≈ <strong>2.86 × 10⁻⁶ m/s²</strong>.','If that additional acceleration remained constant for 10⁶ s, it would change velocity by about <strong>2.86 m/s</strong>.'),'Frame this as the incremental effect of a hypothetical applied force. The asteroid’s real gravitational acceleration is separate. The assumed mass is a scenario parameter, not an observation announced by NASA.')
], 'If force doubles and total mass remains fixed, how does a change? Describe the physical method used to keep mass fixed.','Acceleration doubles in the ideal model. Transfer masses from cart to hanger instead of adding them from outside.','If a student changed both mass and force, preserve the data but redesign a controlled comparison before claiming proportionality.');
L(13,'Net force and F = ma','Find the vector sum of forces before solving for mass or acceleration.','Calculator, whiteboard or paper.','5 min retrieve • 10 min worked example • 10 min model • 17 min practice • 5 min compare • 3 min exit',[
Q('What does F mean?',p('A 5 kg box is pulled with 20 N right while friction acts with 5 N left. Is a = 20/5 the correct acceleration?'),p('No. The net force is 20 − 5 = <strong>15 N right</strong>. a = 15/5 = <strong>3 m/s² right</strong>.'),'Ask for the force inventory and positive axis first. The equation requires net external force, not just the most visible force.'),
S('A signed force sum',eq('ΣFₓ = F<sub>right</sub> − F<sub>left</sub> = maₓ'),p('With right positive, a negative result means acceleration left.','Forces in a perpendicular direction require a separate equation.'),'Vertical weight and normal may cancel on a level surface with no vertical acceleration. They should not be mixed into a scalar horizontal sum.'),
S('Worked force inventory',p('A 5 kg box has 30 N pull right, 10 N friction left, and no vertical acceleration.'),eq('ΣFₓ = +30 − 10 = +20 N'),eq('aₓ = 20/5 = +4 m/s²'),p('Vertically, N − mg = 0, so N = 49 N.'),'Explain why finding the horizontal acceleration does not require subtracting weight. Its direction is perpendicular to the chosen x-axis.'),
S('One change at a time',sim('force'),'Begin mass 5 kg, right force 30 N, left force 10 N. Predict a. Change only mass to 10, then restore it and change only right force to 10. Students record a and explain the zero-net-force case.',{tag:'Controlled model'}),
Q('Solving for a missing applied force',p('A 4 kg box accelerates right at 2 m/s² while friction is 6 N left. Find the rightward applied force.'),eq('Fapplied − 6 = (4)(2)')+eq('Fapplied = 14 N'),'A frequent error is reporting 8 N, which is the net force. Require learners to name which force their calculated number represents.'),
Q('Solving for mass',p('Two horizontal forces act on an object: 18 N right and 6 N left. Its acceleration is 3 m/s² right. Find its mass.'),p('ΣF = 18 − 6 = 12 N. m = 12/3 = <strong>4 kg</strong>.'),'Mass stays positive. A mismatched acceleration direction would signal inconsistent data, not negative mass.'),
Q('Braking force from motion data',p('A 1,500 kg car moves at +30 m/s and stops in 5 s under constant acceleration. Find the net horizontal force.'),eq('a = (0 − 30)/5 = −6 m/s²')+eq('ΣFₓ = 1,500(−6) = −9,000 N'),'This is net horizontal force, not necessarily a single brake force. Ground contact on the tires supplies the main external braking interaction in an ordinary car.'),
Q('Independent practice A',list('m = 8 kg, forces 50 N right and 18 N left. Find a.','m = 3 kg, a = −2 m/s², right force = 4 N. Find the leftward force magnitude.'),p('1. ΣF = 32 N, a = <strong>4 m/s² right</strong>.','2. 4 − L = −6, so L = <strong>10 N</strong>.'),'Have students explain why the second leftward force exceeds the rightward one. The sign of net force must match the sign of acceleration.'),
Q('Independent practice B',list('A 2 kg cart moves left with 5 N right and 5 N left. Describe acceleration and velocity trend.','A net 9 N force gives an object a 1.5 m/s² acceleration. Find mass.'),p('1. a = <strong>0</strong>, so it keeps its current leftward velocity in this model.','2. m = 9/1.5 = <strong>6 kg</strong>.'),'Zero net force does not mean a moving cart stops. Ask for the initial motion when velocity cannot be uniquely inferred.'),
Q('Explaining a result',p('A student writes “−4 m/s², so it moves left.” What does the acceleration actually establish? What additional information is needed?'),p('It establishes that velocity changes in the negative direction by 4 m/s each second. The current velocity is needed to determine the direction of motion and whether speed rises or falls.'),'Use a right-moving braking car as a counterexample. This joins Days 7 and 13 conceptually.')
], 'A 6 kg object experiences 22 N right and 10 N left. Find net force and acceleration with direction.','Net force = 12 N right. Acceleration = 2 m/s² right.','If a single force is substituted, require a labeled signed sum before using F = ma.');
L(14,'Newton’s third law','Identify an interaction pair on two different objects and explain unequal accelerations under equal force magnitudes.','Two connected force sensors or spring scales within ratings, notebook. Online: supplied paired readings.','5 min predict • 10 min explanation • 15 min investigate • 12 min applications • 5 min compare • 3 min exit',[
Q('A large object and a small object interact',p('During a collision between a heavy cart and a light cart, which cart exerts the larger force on the other at the same instant? Predict before discussing.'),p('The interaction forces have equal magnitude and opposite directions at the same instant. Different masses can have different accelerations.'),'Collect individual predictions. Do not confuse total net forces with the specific pair of contact forces.',{deferAnswer:true}),
S('One interaction, two force statements',eq('F<sub>A on B</sub> = −F<sub>B on A</sub>'),p('Both forces exist simultaneously. They have the same type and equal magnitudes, and act on different objects.','Naming the agent and receiver is the most reliable test for a pair.'),'The word reaction does not mean delayed. Have learners literally swap the names of the two objects to identify the partner force.'),
Q('A hand and a wall',p('Your hand pushes on a wall. Write both force statements. Which belongs on a free-body diagram of your hand?'),p('Hand on wall and wall on hand are the pair.','The hand’s diagram includes <strong>wall on hand</strong>. The wall’s diagram includes hand on wall.'),'Ask where each force acts. The forces cannot cancel on the hand’s diagram because only one of the pair acts on the hand.'),
S('Paired-sensor investigation',list('Zero both sensors and connect them along one line. Stay within their load limits.','Choose a common positive axis for both force descriptions.','Predict the two readings for gentle steady and changing pulls.','Record both readings at the same times. Compare magnitudes and signs.','Explain any mismatch using zeroing, calibration, timing, or apparatus effects.'),'A device’s local sign setting may make raw readouts share a sign. Convert to a common axis before comparing vectors. In a two-sensor setup, assume the connecting link has negligible mass and analyze the shared interaction carefully.',{tag:'Investigation 1.4'}),
S('Example paired measurements',table(['Time (s)','A on B (N)','B on A (N)'],[['0.5','+2.0','−2.1'],['1.0','+4.1','−4.0'],['1.5','+3.0','−3.1']]),p('Illustrative readings with small measurement differences. Compare simultaneous values, not different moments.'),'These authored sample readings show plausible measurement noise, not collected data. Do not imply that the law predicts unequal forces. Ask what sensor resolution would make these differences meaningful.',{tag:'Online alternative'}),
Q('Equal forces, unequal accelerations',p('During an ideal interaction, cart A has mass 1 kg and cart B has mass 4 kg. Each experiences a 12 N interaction force, in opposite directions. Ignore other horizontal forces. Find their acceleration magnitudes.'),p('aA = 12/1 = <strong>12 m/s²</strong>. aB = 12/4 = <strong>3 m/s²</strong>.','Equal force magnitudes do not imply equal acceleration magnitudes.'),'The assumption about other horizontal forces allows the interaction force to equal the horizontal net force on each cart.'),
Q('Balanced forces or a third-law pair?',p('A book rests on a table. Its weight and the table’s normal force are equal and opposite. Are they a third-law pair? Identify each force’s actual partner.'),p('No. Both act on the book.','Earth on book pairs with book on Earth. Table on book pairs with book on table.'),'Use the same-object versus different-object test. Equal magnitude and opposite direction alone are insufficient to establish an interaction pair.'),
Q('The horse and cart question',p('The horse pulls the cart forward and the cart pulls the horse backward equally. How can the pair accelerate forward?'),p('For the horse-plus-cart system, those internal forces cancel in the total. The ground’s external forward force on the horse can exceed external resistance, producing a forward net force.'),'Then choose cart alone: horse on cart can exceed backward resistance. System boundaries change the force list but not the physical prediction.'),
Q('The asteroid connection',p('A small spacecraft strikes a much larger asteroid. Compare the contact force magnitudes and the acceleration magnitudes during the interaction.'),p('Contact force magnitudes are equal at each instant. The less massive spacecraft has the greater acceleration magnitude from that interaction.','A spacecraft does not need to survive intact to transfer momentum. Detailed collision analysis comes later.'),'Correct the source suggestion that surviving intact is necessary. Keep this explanation conceptual and do not claim a numerical deflection outcome without more information.')
], 'A foot pushes backward on the ground. Name its interaction partner, and say on which object the partner acts.','The ground pushes forward on the foot. The partner acts on the foot, not the ground.','If pairs are chosen by arrow direction alone, require two agent-on-object sentences with names swapped.');
L(15,'Free-body diagrams','Draw only the external forces acting on one chosen object and label each interaction.','Paper, pencil, ruler.','5 min retrieve • 12 min model • 10 min guided diagrams • 15 min practice • 5 min critique • 3 min exit',[
Q('The phone on the desk',p('Choose the phone as the object. List the external forces on it while it rests on a horizontal desk.'),p('Earth on phone: weight down. Desk on phone: normal up. For rest with no other vertical forces, the magnitudes match.'),'Ask students to draw only after naming the object and interactions. This removes unnecessary scene details.'),
S('A diagram is a force inventory',list('Name the object or system boundary.','Represent it with a dot or simple body outline.','Draw one arrow for each actual external force, starting at the object.','Label the force type and agent. Choose axes.','Use relative arrow lengths when magnitudes are known or constrained.'),'A free-body diagram does not show the path, velocity, or a leftover “motion force.” Keep any velocity arrow outside the force diagram and label it separately.'),
S('Worked horizontal pull',p('A 5 kg box slides right. A horizontal rope pulls with 30 N and kinetic friction is 10 N. No vertical acceleration.'),'<div class="forceplot" data-forces="30,10,49,49" data-labels="T rope,f floor,N floor,Fg Earth"></div>','Draw weight and normal equal because vertical acceleration is zero. The rightward tension arrow is three times the leftward friction arrow. The net force is a result of these arrows, not a fifth interaction.',{tag:'Worked diagram'}),
Q('Guided diagram: hanging lamp',p('A 2 kg lamp hangs motionless from one vertical rope. Draw and label its free-body diagram. Add force magnitudes.'),p('Tension by rope upward: <strong>19.6 N</strong>. Weight by Earth downward: <strong>19.6 N</strong>.','The diagram contains two equal-length vertical arrows.'),'Ask which external object exerts tension. The rope itself has its own force diagram, different from the lamp’s.'),
Q('Guided diagram: a falling ball',p('A ball falls downward with air resistance upward. Its speed is increasing. Draw the force directions and compare their lengths.'),p('Weight points down and is larger than upward drag. The net force and acceleration point down, consistent with increasing downward speed.'),'If students make the arrows equal, ask what that would imply about acceleration. A falling object can later have equal weight and drag at terminal speed.'),
S('Components do not create extra interactions',p('When resolving a force, replace it with its components in the equations.','A component diagram may use dashed guides. Do not count the original force and both components in the same sum.','For a ramp, weight still points vertically downward before decomposition.'),'Use one existing student ramp sketch. Explain that the coordinate axes can rotate while the physical gravitational force remains vertical.'),
Q('Independent diagram set',list('A box slides left across a rough horizontal floor after release.','A ball moves upward after leaving a hand, with air resistance ignored.','A block remains at rest on a rough incline.'),p('1. Weight down, normal up, kinetic friction right.','2. Weight only, down.','3. Weight vertically down, normal perpendicular out, static friction up the incline in this case.'),'Collect all three before revealing. The first case checks friction direction, the second checks residual push, and the third checks normal direction.'),
Q('Critiquing an incorrect diagram',p('A box’s diagram includes weight, normal, friction, a “velocity force,” and an extra net-force arrow. What should change?'),p('Remove the velocity force. Net force is the vector sum of the interaction arrows, so show it separately if needed.','Check that friction has an actual surface source and the direction matches relative slipping or its tendency.'),'An arrow labeled velocity can be useful outside the force diagram, but it must not enter the force sum.'),
Q('An asteroid’s force inventory',p('Model an asteroid away from surfaces with no active engine. Name plausible external interactions. Is “forward motion” an interaction?'),p('Gravitational forces from the Sun, Earth, and other bodies may act. Their relevance depends on the chosen approximation.','Forward motion is a state, not an interaction. No surface contact means no normal force or ordinary surface friction.'),'Do not draw every gravity arrow toward Earth. The Sun and Earth occupy different directions. If geometry is not given, name sources rather than inventing their directions.')
], 'Draw a box sliding right after the hand releases it on a rough level floor. Name every force’s source.','Earth weight down, floor normal up, floor kinetic friction left. No hand force after release.','If extra arrows appear, ask “which external object exerts this force?” and remove quantities without an interaction source.');
L(16,'From force diagrams to acceleration','Write force equations along chosen axes, including a ramp, and calculate the resulting acceleration.','Calculator in degree mode, graph paper, vector reference.','5 min retrieve • 12 min flat-surface work • 15 min ramp model • 12 min practice • 3 min compare • 3 min exit',[
Q('From arrows to a result',p('A 5 kg box has 30 N right and 10 N left. Find its net force and horizontal acceleration.'),p('ΣFₓ = 30 − 10 = <strong>20 N right</strong>. aₓ = 20/5 = <strong>4 m/s² right</strong>.'),'Require the force sum before division. Review the distinction between an individual force and the net force.'),
S('Each axis gets its own equation',eq('ΣFₓ = maₓ'),eq('ΣFᵧ = maᵧ'),p('For a box constrained to a horizontal surface with no vertical acceleration, ΣFᵧ = 0.','Normal force equals weight only if those are the only vertical forces.'),'A vertical component of a pull changes the normal force. Emphasize the condition before using N = mg.'),
Q('An upward-angled pull changes normal force',p('A 5 kg box stays on a horizontal floor with no vertical acceleration. A rope contributes 12 N upward as part of its pull. Find N.'),eq('N + 12 − 49 = 0')+eq('N = 37 N'),'This prevents the automatic N = mg habit. Horizontal forces do not enter the vertical equation.'),
S('Axes along and perpendicular to a ramp',p('For a ramp at angle θ above horizontal, choose +x down the ramp and +y outward from its surface.'),eq('Weight component down ramp = mg sin θ'),eq('Weight component into ramp = mg cos θ'),p('Weight itself still points vertically downward.'),'Construct the geometry on graph paper and label the angle. These formulas follow the specified angle and axes. The normal force is perpendicular to the ramp.'),
S('Worked ramp with given friction',p('A 4 kg box slides down a 30° ramp. Kinetic friction is 5 N up the ramp. No other forces act.'),eq('mg sin 30° = 19.6 N'),eq('ΣFₓ = 19.6 − 5 = 14.6 N'),eq('aₓ = 14.6 / 4 = 3.65 m/s²'),'The perpendicular equation gives N = mg cos30° ≈ 33.9 N because perpendicular acceleration is zero. Do not subtract friction from the normal force.',{tag:'Worked example'}),
Q('Guided frictionless ramp',p('A 2 kg cart travels down an ideal frictionless 20° ramp. Find its acceleration and normal force.'),p('a = g sin20° ≈ <strong>3.35 m/s² down the ramp</strong>.','N = mg cos20° ≈ <strong>18.4 N</strong>.'),'Mass cancels in the acceleration expression. This ideal model neglects rotational effects of wheels, so describe it as a particle/cart approximation.'),
Q('A box moving up can accelerate down',p('A block slides up a rough ramp after a push ends. Which way do gravity’s ramp component and kinetic friction point? What happens to speed?'),p('Both point down the ramp. The block’s acceleration points down the ramp while its velocity points up, so it slows.'),'Friction changes direction when the relative slip reverses. Avoid keeping the friction direction from a previous down-ramp example.'),
Q('Independent flat-surface case',p('A 10 kg box is pulled 50 N right with friction 15 N left. Find net force and acceleration. Assume no vertical acceleration and a horizontal pull.'),p('ΣFₓ = <strong>35 N right</strong>. aₓ = <strong>3.5 m/s² right</strong>. N = 98 N.'),'The first two quantities assess the core target. Include the vertical condition if asking students to calculate normal force.'),
Q('Independent ramp case',p('A 5 kg box slides down a 30° ramp with 9.5 N friction up the ramp. Find the net force and acceleration along it.'),p('Down-ramp weight = (5)(9.8)(0.5) = 24.5 N.','ΣF = 24.5 − 9.5 = <strong>15 N down</strong>. a = <strong>3.0 m/s² down</strong>.'),'Check that learners use the component 24.5 N, not the full 49 N weight, in the ramp-direction sum.'),
Q('Why axes are a choice',p('Would choosing +x up the ramp change the physical acceleration in the worked 4 kg example? Explain how its sign changes.'),p('The same physical acceleration remains 3.65 m/s² down the ramp. Its coordinate becomes <strong>−3.65 m/s²</strong> when up the ramp is positive.'),'This reinforces that coordinate conventions change the numbers’ signs, not the motion.')
], 'A 2 kg block slides down a 30° ramp with 3.8 N friction up it. Find acceleration.','Down-ramp weight = 9.8 N, net = 6.0 N down, a = 3.0 m/s² down.','If full weight enters the ramp sum, return to the perpendicular components and label which axis each term occupies.');
L(17,'Static and kinetic friction','Distinguish adjustable static friction from kinetic friction and determine when slipping begins.','Block with sliding pad, force sensor or spring scale, balance, level surface. Use a sliding block, not a freely rolling cart.','5 min predict • 10 min model • 18 min investigate • 12 min practice • 2 min compare • 3 min exit',[
Q('A push that does not move the box',p('A horizontal push of 5 N acts on a box at rest on a rough level floor. What is the static friction force, if nothing else pushes horizontally?'),p('Static friction is <strong>5 N</strong> in the opposite direction. It adjusts to prevent slipping up to its maximum.'),'Do not start by calculating μsN as the actual friction. That expression is the limiting value.'),
S('Two friction models',eq('0 ≤ f<sub>s</sub> ≤ μ<sub>s</sub>N'),eq('f<sub>k</sub> ≈ μ<sub>k</sub>N'),p('Static friction adjusts while the contact does not slip. Kinetic friction models sliding contact.','The coefficients depend on the contacting surfaces and conditions.'),'These are useful approximate dry-friction models. They do not describe all rolling resistance, lubrication, or speed effects. The direction opposes relative slip or its tendency at the contact.'),
Q('Before and after slipping',p('A 5 kg box has μs = 0.40 and μk = 0.30. A horizontal 12 N push acts on a level floor. Find N, the maximum static friction, and the actual friction.'),p('N = 49 N. fs,max = 0.40(49) = <strong>19.6 N</strong>.','Since 12 N is below that limit, actual fs = <strong>12 N</strong> opposite the push. The box stays at rest.'),'If students report 19.6 N as actual friction, ask what net force that would produce and why a box at rest would then accelerate backward.'),
Q('The same box with a larger push',p('The push rises to 25 N and the same box begins sliding. Find kinetic friction and acceleration.'),p('fk = 0.30(49) = <strong>14.7 N</strong>.','ΣF = 25 − 14.7 = 10.3 N. a = 10.3/5 = <strong>2.06 m/s²</strong>.'),'The 25 N push exceeds the static threshold. Once sliding, use the kinetic coefficient supplied for this model.'),
S('Measuring the two coefficients',list('Measure the sliding block’s mass. Pull horizontally with a zeroed force sensor.','Increase the pull slowly until slipping begins. Record the peak just before sliding.','Then pull at approximately constant speed and average the steady sliding force.','Repeat three times. Compute μs ≈ Fpeak/N and μk ≈ Fsteady/N.','Record surfaces, mass, trial spread, and sources of uncertainty.'),'Use a sliding block or locked-wheel cart. A freely rolling cart measures rolling resistance, not the same sliding friction coefficient. An upward pull changes N and invalidates N = mg unless included.',{tag:'Investigation 1.5'}),
S('Practice force-trace data',table(['Trial','Peak (N)','Steady sliding (N)'],[['1','8.0','5.8'],['2','8.4','6.0'],['3','8.2','5.9']]),p('Authored example for a 2.00 kg sliding block with horizontal pull. N = 19.6 N.'),'The steady force equals friction only when speed is approximately constant. During the initial acceleration, measured pull and friction need not match.',{tag:'Online alternative'}),
Q('Analyzing the data',p('Using the example trials, calculate mean peak and steady forces. Estimate μs and μk.'),p('Mean peak = <strong>8.2 N</strong>, mean steady = <strong>5.9 N</strong>.','μs ≈ 8.2/19.6 = <strong>0.42</strong>, μk ≈ 5.9/19.6 = <strong>0.30</strong>.'),'Report coefficients without units. Reasonable rounding is appropriate given the precision of the sample values. Students should preserve all three trials.'),
Q('Friction can point forward',p('A person walks forward without slipping. The foot pushes backward on the ground. Which way does the ground’s friction force on the foot point?'),p('Forward. Static friction prevents the foot from slipping backward relative to the ground and helps propel the person.'),'This corrects “friction always opposes motion.” It opposes relative slipping at the contact, which can differ from the object’s overall motion.'),
Q('Independent threshold check',p('A 10 kg box has μs = 0.50 and μk = 0.40. Compare a 30 N horizontal push and a 60 N push, starting from rest each time.'),p('N = 98 N, fs,max = 49 N. With 30 N, fs = <strong>30 N</strong> and a = 0.','With 60 N, it slips: fk = 39.2 N, a = (60 − 39.2)/10 = <strong>2.08 m/s²</strong>.'),'Require a threshold decision before any acceleration calculation. The kinetic formula cannot be applied automatically to a stationary box.')
], 'A box has maximum static friction 15 N. You push with 9 N and it stays still. What is actual friction? What if the push rises above 15 N?','Actual static friction = 9 N opposite the push. Above 15 N it starts slipping, so the kinetic model applies if its coefficient is known.','If static friction is always set to its maximum, return to force balance for several subthreshold pushes.');
L(18,'Equilibrium and unknown forces','Recognize constant velocity as equilibrium and solve balanced-force equations in one or two dimensions.','Calculator in degree mode, paper.','5 min retrieve • 10 min core cases • 15 min two-rope model • 12 min practice • 5 min explain • 3 min exit',[
Q('Parked or cruising?',p('A parked truck and a truck moving straight at constant speed are observed over a steady interval. Which has zero net force?'),p('Both. Their velocities are constant, so acceleration is zero. A turn or speed change would make the second case different.'),'Require “straight” for the moving case. Constant speed around a curve is not translational equilibrium.'),
S('Translational equilibrium',eq('ΣFₓ = 0 and ΣFᵧ = 0'),p('Forces balance in every direction. Velocity stays constant and may be zero.','For extended objects, avoiding rotation also requires torque balance. Today we treat objects as particles or use symmetric arrangements.'),'This carefully scopes equilibrium to the current course tools. A zero net force alone does not exclude rotational acceleration of an extended object.'),
Q('A single hanging lamp',p('A 5 kg lamp hangs motionless from one vertical rope. Find the tension.'),eq('T − mg = 0')+eq('T = (5)(9.8) = 49 N'),'This is the core exit target in the original lesson. Extend only after every student can explain the equilibrium condition.'),
Q('A moving box in equilibrium',p('A rope pulls a box right at constant velocity on a rough level floor. Tension is 20 N. Find horizontal friction.'),p('ΣFₓ = 20 − f = 0, so friction = <strong>20 N left</strong>.'),'The mass is not needed for this force balance. A student who asks for mass may be treating every problem as a plug-in F=ma calculation.'),
S('A symmetric two-rope setup',p('A 10 kg sign hangs from two identical ropes, each at 30° above horizontal. The arrangement is symmetric.'),eq('Horizontal: T cos30° − T cos30° = 0'),eq('Vertical: 2T sin30° − 98 = 0'),eq('T = 98 N in each rope'),'The angle is measured from horizontal, so the vertical component uses sine. The two full tensions do not simply add to weight because each tension has a horizontal component.',{tag:'Worked example'}),
Q('A steeper rope angle',p('For the same 10 kg sign, each rope is now 60° above horizontal. Find each tension and compare it with the 30° case.'),eq('T = 98 / (2 sin60°) ≈ 56.6 N')+p('Steeper ropes need less tension because more of each tension acts vertically.'),'The ideal model predicts increasing tension as the angle approaches horizontal. Do not test near-horizontal support with real loads in class.'),
Q('Guided equilibrium with two unequal forces',p('A stationary object has a 12 N force right and a 9 N force upward. A third force balances them. Find its components and magnitude.'),p('The third force is <strong>(−12, −9) N</strong>. Magnitude = √(12² + 9²) = <strong>15 N</strong>, directed down and left.'),'Equilibrium means each component sums to zero. The third force is the negative of the resultant of the first two.'),
Q('Independent two-rope case',p('A 4 kg lamp hangs symmetrically from two ropes at 45° above horizontal. Find the tension in each rope.'),p('Weight = 39.2 N. 2T sin45° = 39.2.','T ≈ <strong>27.7 N</strong> in each rope.'),'Require students to check that 2(27.7)sin45° ≈ 39.2 N. The sum of full tension magnitudes is larger than the weight.'),
Q('Is an orbit equilibrium?',p('An object travels in a circular orbit at constant speed. Does it have zero net force? Explain using velocity.'),p('No. Its velocity direction changes, so it accelerates. A nonzero net force points toward the center in the circular model.'),'This previews Unit 2. Avoid saying an asteroid is “close to equilibrium” solely because an acceleration number seems small. Specify the time interval and acceptable approximation instead.')
], 'A 3 kg lamp hangs from one vertical rope at rest. Find tension. Would the same tension apply if it accelerated upward?','At rest, T = 29.4 N. Upward acceleration requires T > 29.4 N.','If moving objects are excluded from equilibrium, compare constant-velocity and accelerating motion explicitly.');
L(19,'Workshop: diagnose, repair, recheck','Use evidence to identify a weak skill, correct it, and demonstrate improvement on a different problem.','Notebook, calculator, graph paper, prior exit tickets.','7 min diagnostic • 3 min choose • 15 min repair • 15 min practice • 7 min recheck • 3 min exit',[
S('Evidence chooses the workshop',p('Complete the four diagnostic questions independently. Compare your work with the feedback.','Choose the station where your explanation or method needs the most work.','A useful revision names the error and shows a corrected approach on a new case.'),'Do not let confidence ratings alone determine station placement. Ask students to bring an actual exit ticket or diagnostic result as evidence. Online learners use the same sequence.'),
Q('Diagnostic A: motion graphs',p('A straight x–t line connects (0 s, 7 m) and (3 s, 1 m). Find velocity. Is 1 m the displacement?'),p('v = (1 − 7)/3 = <strong>−2 m/s</strong>. Displacement = <strong>−6 m</strong>. The 1 m value is final position.'),'Route slope/coordinate errors to Station A.',{tag:'Diagnostic'}),
Q('Diagnostic B: vectors',p('Resolve a 10 N force 30° north of east.'),p('Fₓ ≈ <strong>8.66 N east</strong>, Fᵧ = <strong>5.00 N north</strong>.'),'Route angle or component errors to Station B.',{tag:'Diagnostic'}),
Q('Diagnostic C: forces',p('A 4 kg object has forces 18 N right and 6 N left. Find a. Name the third-law partner of Earth’s pull on the object.'),p('a = (18 − 6)/4 = <strong>3 m/s² right</strong>.','The partner is the object’s gravitational pull on Earth.'),'Route net-force or interaction-pair errors to Station C.',{tag:'Diagnostic'}),
Q('Diagnostic D: prediction and bounds',p('x₀ = 5 ± 1 m, v = 2 ± 0.2 m/s, t = 10 s. Give the central position and interval.'),p('Central x = <strong>25 m</strong>. Half-width = 1 + 2 = <strong>3 m</strong>. Interval <strong>22–28 m</strong>.'),'Route conversion, initial-position, or uncertainty errors to Station D.',{tag:'Diagnostic'}),
S('Station A: slope and motion',p('<strong>Repair:</strong> Label the axes. Circle two points. Subtract coordinates in matching order, then divide Δx by Δt.','<strong>Example:</strong> (1 s, 2 m) to (4 s, 8 m) gives (8−2)/(4−1) = +2 m/s.','<strong>Try:</strong> (2 s, 9 m) to (6 s, 1 m). Explain what a horizontal x–t segment means.'),'Give this station 8–10 minutes, then require a fresh case. Answer to the try: −2 m/s, horizontal means position remains constant. Point students to Day 3 for a full explanation.'),
S('Station B: vector components',p('<strong>Repair:</strong> Draw the angle from its stated axis. Mark adjacent and opposite components. Decide signs from the quadrant.','<strong>Example:</strong> 10 N at 30° above +x gives (8.66, 5.00) N.','<strong>Try:</strong> 12 N at 60° south of east. Check the component sizes against your sketch.'),'Try answer: (+6.00, −10.39) N. If signs fail, temporarily remove trigonometry and ask only for the quadrant. Day 6 has the full method.'),
S('Station C: force sum and object boundary',p('<strong>Repair:</strong> Name one object, list external agents, draw forces, then sum along one axis.','<strong>Example:</strong> A 2 kg object with 10 N right and 4 N left has a = (10−4)/2 = 3 m/s² right.','<strong>Try:</strong> A 3 kg object has 4 N right and 10 N left. Describe a and what extra information determines its motion direction.'),'Try answer: a = −2 m/s² with right positive. Current velocity is needed to know direction of motion. Use Days 13–15 for support.'),
S('Station D: position and uncertainty',p('<strong>Repair:</strong> Convert units. Find central x₀+vt. Then calculate δx₀+tδv. State lower and upper bounds.','<strong>Example:</strong> 10±1 m plus (2±0.1 m/s)(5 s) gives 20±1.5 m.','<strong>Try:</strong> 20±2 m plus (−1±0.2 m/s)(5 s).'),'Try answer: 15±3 m, interval 12–18 m. Ask the learner to verify by calculating the two extreme input combinations. Day 5 explains the bound model.'),
Q('Practice feedback',p('Compare your station’s “Try” result. Write one correction before moving to a new question.'),list('A: −2 m/s. Horizontal x–t means rest.','B: (+6.00, −10.39) N.','C: −2 m/s². Need current velocity to know motion direction.','D: 15±3 m, interval 12–18 m.'),'This feedback is deliberately separate from the station instructions. Have students explain one discrepancy instead of just changing the answer.'),
Q('Fresh recheck',list('A: (1 s, 10 m) to (5 s, 2 m). Find v.','B: 8 N at 30° south of east. Find components.','C: m = 5 kg, 7 N right, 22 N left. Find a.','D: x₀ = 3±1 m, v = 4±0.5 m/s, t = 2 s. Give interval.'),p('A: <strong>−2 m/s</strong>. B: <strong>(+6.93, −4.00) N</strong>.','C: <strong>−3 m/s²</strong>. D: central 11 m, interval <strong>9–13 m</strong>.'),'Students must complete the question for their chosen station without copying the worked example. Fast finishers do all four and explain the model assumptions.',{tag:'Independent recheck'}),
S('A revision record',p('My original error was ______.','The corrected method is ______ because ______.','On the new problem, I showed ______.','The next skill I need to practice is ______.'),'Keep the actual original and new work together. A claim of improvement needs observable evidence.')
], 'Submit your original attempt, corrected method, and fresh recheck. Explain one decision you can now make independently.','Look for a specific corrected method demonstrated on a different problem, not just a copied answer.','If the recheck remains incorrect, use a short teacher conference and another changed case before the transfer task.');
L(20,'Synthesis: a complete prediction','Connect forces, motion models, vector components, uncertainty, and a public explanation in one coherent analysis.','Calculator, graph paper, vector reference.','5 min retrieve • 15 min worked case • 18 min group case • 7 min compare • 2 min reflection • 3 min exit',[
S('The chain of reasoning',list('Choose the object and coordinate frame.','Identify forces and decide what motion model is reasonable.','Resolve velocity into components.','Predict position over a stated elapsed time.','Propagate the supplied measurement bounds.','Explain the result and the model’s limits.'),'Use this as the organizing structure, not a substitute for worked content. Each step answers a distinct question. The assessment focuses primarily on the kinematic prediction and its justification.'),
S('Worked case: a fictional probe',p('In a local inertial toy model, a probe begins at (−100 km, 0). Its velocity is (4, 3) km/s and remains constant for 20 s.','Initial x bound: ±1 km. Component velocity bounds: ±0.1 km/s independently. y₀ is exact.','No appreciable net external force acts during this short model interval.'),'These values differ from the assessment. Independent component bounds here are deliberately different from the fixed-angle speed bound in the asteroid task. Call out that modeling choice.',{tag:'Worked case'}),
Q('Worked case: endpoint and separation',p('Find the probe’s final coordinates, displacement magnitude, and separation from the origin.'),p('x = −100 + 4(20) = <strong>−20 km</strong>. y = 0 + 3(20) = <strong>60 km</strong>.','Displacement = (80,60) km, magnitude <strong>100 km</strong>. Separation from origin = √(20²+60²) ≈ <strong>63.2 km</strong>.'),'Use this case to distinguish three often-confused results: coordinates, displacement, and separation. Students should label each explicitly.'),
Q('Worked case: the bounds',p('Calculate the endpoint bounds using the supplied independent component uncertainties.'),p('δx = 1 + 20(0.1) = <strong>3 km</strong>, so x lies from <strong>−23 to −17 km</strong>.','δy = 20(0.1) = <strong>2 km</strong>, so y lies from <strong>58 to 62 km</strong>.'),'The rectangle is a conservative coordinate box for the specified independent bounds. It does not include uncertainty in acceleration or frame choice.'),
S('Worked public explanation',p('“Under our constant-velocity model, the probe should reach about 20 km left and 60 km above the origin after 20 seconds. The measurement bounds give x from −23 to −17 km and y from 58 to 62 km. This forecast assumes the velocity does not change. New forces or better measurements would require us to update it.”'),'Ask students to identify the result, evidence of uncertainty, and limitation. Technical equations belong in the supporting work, while the public paragraph explains their meaning.'),
Q('Group case: changed conditions',p('A fictional probe begins at (−80 km, 0). It moves at 5 km/s, 30° above +x, for 10 s. Initial x bound is ±0.5 km. Speed bound is ±0.2 km/s at an exact angle.','Produce: a force-model statement, velocity components, endpoint, coordinate bounds, and a short public explanation.'),p('vₓ ≈ <strong>4.330 km/s</strong>, vᵧ = <strong>2.500 km/s</strong>.','Endpoint ≈ <strong>(−36.70, +25.00) km</strong>. δx ≈ <strong>2.23 km</strong>, δy = <strong>1.00 km</strong>.'),'Students should explicitly assume negligible net force for the constant-velocity case. Bounds follow δvcosθ and δvsinθ. The same uncertain speed drives both components, so their errors are correlated.',{tag:'18-minute group application'}),
Q('The graph is evidence too',p('For the group case, state two endpoints for the central x–t line and the upper/lower x bounds at t = 0 and t = 10 s.'),p('Central: <strong>(0, −80)</strong> to <strong>(10, −36.70)</strong>, in s and km.','At t = 0: −80.5 to −79.5 km. At 10 s: approximately <strong>−38.93 to −34.47 km</strong>.'),'Require axes, units, central line, and labeled bounds. A perspective drawing of a trajectory cannot substitute for a position-component vs time graph.'),
Q('A new force changes the prediction',p('A 1,000 kg probe experiences a constant net force of +200 N along x for 10 s. Find the extra Δvₓ and extra displacement relative to a constant-velocity prediction with the same initial state.'),p('aₓ = 200/1,000 = <strong>0.20 m/s²</strong>.','Extra Δvₓ = <strong>2 m/s</strong>. Extra Δx = ½(0.20)(10²) = <strong>10 m</strong>.'),'Units change from km in the previous case to SI here. Make this explicit. The added displacement is 0.010 km, not 10 km.'),
Q('What the asteroid calculation can establish',p('Can a straight-line prediction using six months of constant velocity establish whether the fictional asteroid will collide with the real moving Earth?'),p('No. It is a teaching model that demonstrates tools. A real encounter prediction must include gravitational changes, Earth’s motion, the full three-dimensional state, and measurement/model uncertainty.'),'This is the intellectual conclusion of the unit: the arithmetic has meaning only within its assumptions. Do not imply that the narrative’s encounter date was derived from the toy data.'),
S('Tomorrow’s independent evidence',p('You will submit velocity components, a position prediction, uncertainty bounds, a labeled position–time graph, and a public briefing.','Use the vector recipe card and calculator. Explain your choices in your own words.','A complete analysis shows what the model predicts and what it cannot establish.'),'Avoid giving the assessment’s numeric answers here. Use only the distinct practice cases. Students may review their work and reference cards according to the lesson-plan norms.')
], 'Name one model assumption, one calculation you can justify, and one limitation a public briefing must disclose.','Responses should connect the assumption to the chosen equation and distinguish measurement bounds from omitted physical effects.','Use specific exit evidence to target a short pre-assessment review, without coaching the assessment solution.');
L(21,'Transfer task: receive, plan, begin','Plan and begin an independent vector position prediction, including measurement bounds and explicit assumptions.','Calculator, vector recipe card, graph paper, task data below. Teacher holds completed work between meetings.','5 min norms • 10 min read • 10 min plan • 20 min independent work • 5 min checkpoint',[
S('The assessment scenario',p('The fictional 2026-XJ story now calls for a refined trajectory briefing. Your assignment is to analyze a simplified six-month prediction.','The story’s “close pass” is narrative context. <strong>The supplied straight-line model cannot establish an actual future encounter.</strong>','This is fiction. The physics is real.'),'Keep the scenario designation separate from real NASA communications. Give task clarification but no physics-content coaching during independent work.',{dark:true}),
S('The given data',table(['Quantity','Supplied value'],[['Initial position','x₀ = −1.2 × 10⁸ km, y₀ = 0'],['Speed','8,500 m/s'],['Direction','15° from +x toward +y'],['Elapsed time','1.6 × 10⁷ s'],['Initial x bound','±50,000 km'],['Speed bound','±200 m/s']]),'These preserve the source’s numerical data while resolving its missing coordinate convention. Treat y₀, the angle, and elapsed time as exact in the classroom calculation. Give all students the same clarification.'),
S('The coordinate convention',p('Earth is fixed at the origin in this toy model. +x points from the initial asteroid position toward Earth. +y is perpendicular in the diagram plane.','The initial asteroid lies on the negative x-axis. Its velocity points 15° above +x.','Keep these axes fixed throughout the calculation.'),'The source phrase “15° toward Earth” was ambiguous. This convention is an explicit clarification, not a new measured fact. Students may use a consistent equivalent convention if their transformation is clear.'),
S('The model and the bounds',list('Assume constant velocity for the entire interval as a deliberate teaching simplification.','Propagate the speed bound at the fixed 15° direction.','Let the initial x bound vary independently of speed.','Treat the angle, y₀, and elapsed time as exact for these bounds.','Discuss gravitational changes and Earth’s motion as excluded model effects.'),'Do not justify negligible acceleration from the original loose “<0.001 m/s²” statement. This task explicitly imposes constant velocity, and students must critique that assumption.'),
S('Five required products',list('Velocity components with units and directions.','Final x and y coordinates, with the calculation shown.','Coordinate uncertainty bounds and a clear distinction between half-width and full width.','A position-component vs time graph with central and bounding lines.','A public paragraph explaining the prediction, uncertainty, and limitations.'),'The original packet lists five products even though some plans call them four parts. We preserve all five and make the graph requirement explicit. Students may graph x; an additional y graph is optional.'),
S('What the rubric looks for',table(['Dimension','Visible evidence'],[['Science','Correct quantities, equations, signs, units, and bounds'],['Reasoning','A defensible method with stated assumptions'],['Communication','Readable work and a labeled graph'],['Transfer to asteroid','An honest explanation of what the model does and does not establish']]),'Use the source four-dimension rubric, scored independently 0–4. Do not average dimensions or replace the formal assessment scale with the daily 1–3 self-rating.'),
S('Allowed resources and independent work',p('Use the calculator, graph paper, and vector recipe card. Ask clarifying questions about the task’s wording.','Choose and explain the physics method yourself.','Keep your work for the second session using the teacher’s collection process. Online learners follow the assigned submission process.'),'The source lesson permits the vector card and calculator, but not textbook or content coaching. Honor required accommodations. This deck is an assessment guide, so it contains no numeric solution reveals.'),
S('A plan before the calculation',p('Write a short plan that identifies the units you will use, the quantities you need to find, and the order of your work.','Mark the task products each step will support.','Reserve time for the graph and public explanation.'),'Do not turn this into a formula-by-formula scaffold during assessment. Students demonstrate planning by connecting their own sequence to required outputs.'),
S('An evidence checklist while working',list('My signs agree with my labeled axes.','I can distinguish position, displacement, and separation.','I have labeled each uncertainty as a half-width or full width.','My graph has time and position units.','My explanation identifies a limitation of the physical model.'),'Read the checklist neutrally. Do not point to a specific student calculation and tell them which sign or equation is wrong.'),
S('End-of-session checkpoint',p('Identify completed products and mark the next unfinished step.','Write one specific priority for the next session.','Save or submit your work as directed. Keep the original calculations so your reasoning remains visible.'),'Collect work or use the established LMS process. Record progress without scoring incomplete work as a final profile.')
], 'Submit or save your partial analysis and a one-sentence plan for the next session.','Check for a meaningful plan and visible independent work. Numerical solutions remain in the separate teacher key.','Provide logistical or wording clarification. Reserve content feedback until the assessment and defense are complete.');
L(22,'Transfer task: defend, revise, submit','Complete the prediction, defend the reasoning, and make an evidence-based revision.','Work from Day 21, rubric, calculator, graph paper.','5 min triage • 20 min finish • 14 min peer defense • 8 min revise • 3 min submit',[
S('One priority for the first work block',p('Retrieve your plan and partial work. Compare them with the five required products.','Choose the most important unfinished part and complete it first.','Then check whether another person can follow your method.'),'Give students the first five minutes to triage silently. A student who finished early can audit communication and model limitations, rather than receive a new unannounced task.'),
S('Completion checklist',list('Components with axes, units, and signs.','Final coordinates and supporting calculations.','Measurement bounds with their stated assumptions.','Position–time graph with labeled central and bounding lines.','Public explanation that distinguishes a model prediction from a real encounter forecast.'),'This repeats the product requirements deliberately for the second day. It does not supply the numeric key.'),
S('A defensible public paragraph',p('State the predicted position in words a non-specialist can understand.','Explain the range of possible coordinates under the supplied bounds.','Name what better observations could improve.','Explain why omitted physical effects prevent this calculation from being a complete orbital forecast.'),'Evaluate the student’s own writing. Avoid awarding reasoning credit merely for copying a supplied sentence frame.'),
S('Peer defense: two equal turns',p('<strong>First 7 minutes:</strong> A explains for 4 minutes. B asks questions and records evidence for 3 minutes.','<strong>Next 7 minutes:</strong> switch roles.','Listen for the reasoning behind the method. Record one specific strength and one question that could improve the work.'),'The timing fits a 50-minute lesson. Pair students intentionally when needed for language access. Peer feedback informs revision, while the teacher assigns the formal rubric profile.'),
S('Questions that probe reasoning',list('What does your chosen origin represent?','How did you decide the component signs?','What quantity does this number represent?','Which uncertainties are included in your range?','What could make the real motion differ from this model?'),'Questions should invite explanation, not give away a formula or answer. Students can use their own work as evidence during the defense.'),
S('Feedback names evidence',p('Useful: “Your graph labels kilometers, but your calculation uses meters. Show where you converted.”','Useful: “Your paragraph gives an exact location. Where does your uncertainty calculation appear in the explanation?”','Record the relevant line, graph feature, or missing explanation.'),'These are general examples of feedback quality. Do not tell peers to certify every calculation. A partner’s agreement is not proof of correctness.'),
S('A revision with a reason',p('Choose one substantive improvement based on the defense.','Keep the original visible and annotate what you changed.','Write: “I changed ____ because ____.”','If you keep a challenged claim, defend it with evidence.'),'Revisions can improve reasoning or communication as well as arithmetic. A neat rewrite alone is insufficient evidence of conceptual improvement.'),
S('Self-assessment uses the four dimensions',table(['Dimension','Record your rating and evidence'],[['Science','0–4 with a specific example'],['Reasoning','0–4 with a justified choice'],['Communication','0–4 with a clear feature'],['Transfer to asteroid','0–4 with a meaningful limitation']]),'Use the full source rubric in the teacher guide. Score dimensions independently. Keep letter-grade conversion subject to the school’s current policy rather than inferring it from an old example.'),
S('Final submission',list('Completed analysis and graph.','Public briefing paragraph.','Four-dimension self-assessment with evidence.','Peer-defense note and one documented revision.','One question that the next unit should help answer.'),'Check completion before students leave. Report the rubric profile and target-specific feedback after reviewing the work. The source permits revision within two weeks with new evidence.'),
S('The next question: why does the path curve?',p('Unit 1 built tools for describing motion and connecting force to acceleration.','The next unit develops gravity and orbital motion so we can examine how velocity changes along a trajectory.','Return to your Day 1 question. Identify what you can now explain and what still needs evidence.'),'End by reconnecting to the original questions. Acknowledge that a useful simplified model also reveals what must be learned next.',{dark:true})
], 'Name your most important revision and the evidence that supports it. Submit the complete analysis.','A strong response identifies a specific improvement in physics, reasoning, communication, or the asteroid connection.','Score the four dimensions separately and assign follow-up practice from the actual evidence.');
